async function logAudit(action: string, entityType: string, entityId?: string, details?: any) {
  try {
    const user = await getCurrentUser();
    await db.auditLog.create({
      data: {
        userId: user?.id || null,
        action,
        entityType,
        entityId,
        details,
      }
    });
  } catch (e) {
    console.error("Failed to log audit event:", e);
  }
}

async function getUniqueSlug(baseSlug: string, currentId?: string): Promise<string> {
  let slug = baseSlug.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  if (!slug) slug = "article-" + Math.floor(Math.random() * 10000);

  let candidate = slug;
  let count = 1;
  while (true) {
    const existing = await db.article.findUnique({
      where: { slug: candidate },
      select: { id: true },
    });
    if (!existing || (currentId && existing.id === currentId)) {
      return candidate;
    }
    candidate = `${slug}-${count}`;
    count++;
  }
}

export async function upsertArticle(data: any) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return { success: false, error: "Unauthenticated" };
    }

    const dbUser = await db.user.findUnique({
      where: { id: user.id },
      include: { authorProfile: true }
    });

    if (!dbUser) {
      return { success: false, error: "User record not found" };
    }

    const userWithAuth = {
      id: dbUser.id,
      role: dbUser.role as Role,
      authorId: dbUser.authorProfile?.id || null,
    };

    let existingArticle = null;
    if (data.id) {
      existingArticle = await db.article.findUnique({
        where: { id: data.id },
        select: { id: true, authorId: true, updatedAt: true, status: true, publishedAt: true, slug: true }
      });
      if (!existingArticle) {
        return { success: false, error: "Article not found" };
      }
    }

    const editPolicy = canEditArticle(userWithAuth, existingArticle || undefined);
    if (!editPolicy.success) {
      return { success: false, error: editPolicy.error };
    }

    // Concurrency check – skip on autosave (the editor's baseline will resync from the returned updatedAt)
    // Only block on explicit manual saves where the user could overwrite a co-author's changes
    if (existingArticle && data.lastUpdatedAt && !data.isAutosave) {
      const clientDate = new Date(data.lastUpdatedAt);
      // Allow up to 1 second difference to account for timestamp precision mismatches 
      // between JavaScript Date (milliseconds) and PostgreSQL (microseconds)
      if (existingArticle.updatedAt.getTime() - clientDate.getTime() > 1000) {
        return { 
          success: false,
          serverUpdatedAt: existingArticle.updatedAt.toISOString(),
          error: "Conflict: This article has been modified by someone else since you opened it. Please refresh and integrate your changes." 
        };
      }
    }

    if (!data.title || typeof data.title !== "string" || !data.title.trim()) {
      return { success: false, error: "Article title is required." };
    }

    if (data.img && !isValidSafeUrl(data.img, ALLOWED_MEDIA_DOMAINS)) {
      return { success: false, error: "Featured image URL is invalid or from an unapproved domain." };
    }

    const categorySlug = (data.cat || "technology").toLowerCase().trim();

    // Find category
    const category = await db.category.findUnique({
      where: { slug: categorySlug },
    });

    if (!category) {
      return { success: false, error: "Invalid category selected." };
    }

    const uniqueSlug = await getUniqueSlug(data.slug || data.title, data.id);

    const scheduledFor = data.scheduledFor ? new Date(data.scheduledFor) : null;


    const sanitizedBodyHtml = sanitizeArticleHtml(data.bodyHtml);

    const payload = {
      title: data.title.trim(),
      slug: uniqueSlug,
      status: data.status || "DRAFT",
      deck: data.deck || null,
      contentHtml: sanitizedBodyHtml || null,
      contentJson: data.bodyJson || null,
      author: data.author?.trim() || user.name || "xSypher Staff",
      role: data.role?.trim() || user.role || null,
      featured: typeof data.featured === "boolean" ? data.featured : deriveIsFeatured(data.homepagePlacement || null),
      img: data.img || null,
      seoTitle: data.seoTitle || null,
      seoDesc: data.seoDesc || null,

      homepagePlacement: data.homepagePlacement || null,
      categoryId: category.id,
      scheduledFor,
      readingTime: calculateReadTime(sanitizedBodyHtml || data.bodyHtml),
    };

    let article;
    let actionType = "";
    let existingArticleStatus = "NEW";

    const tagsData = Array.isArray(data.tags) ? data.tags.filter(Boolean).map((slug: string) => ({ slug })) : [];
    if (data.id) {
      const existingArticleForStatus = await db.article.findUnique({ where: { id: data.id }, select: { slug: true, status: true } });
      existingArticleStatus = existingArticleForStatus?.status || "NEW";

      let finalStatusUpdate: ArticleStatus | undefined = undefined;
      // State Demotion logic
      if (dbUser.role === "AUTHOR" && ["PUBLISHED", "APPROVED", "SCHEDULED"].includes(existingArticleStatus)) {
        finalStatusUpdate = "SUBMITTED";
      }

      // Compute slug history for redirect safety
      const currentPreviousSlugs: string[] = (existingArticle as any)?.previousSlugs || [];
      const updatedPreviousSlugs = existingArticle && existingArticle.slug !== uniqueSlug
        ? Array.from(new Set([...currentPreviousSlugs, existingArticle.slug]))
        : currentPreviousSlugs;

      article = await db.article.update({
        where: { id: data.id },
        data: {
          ...payload,
          ...(finalStatusUpdate ? { status: finalStatusUpdate } : {}),
          previousSlugs: updatedPreviousSlugs,
          tags: { 
            set: [], // Clear existing tags to prevent unique constraint failures when changing tags
            connectOrCreate: tagsData.map((t: any) => ({
              where: { slug: t.slug },
              create: { slug: t.slug, name: t.slug }
            }))
          }
        },
        include: { category: true },
      });
      actionType = finalStatusUpdate ? `DEMOTED_TO_${finalStatusUpdate}` : `UPDATE_ARTICLE_${article.status}`;
    } else {
      const resolvedAuthorId = dbUser.role === "AUTHOR" ? userWithAuth.authorId : (data.authorId || userWithAuth.authorId || null);

      article = await db.article.create({
        data: {
          ...payload,
          authorId: resolvedAuthorId,
          tags: tagsData.length > 0 ? {
            connectOrCreate: tagsData.map((t: any) => ({
              where: { slug: t.slug },
              create: { slug: t.slug, name: t.slug }
            }))
          } : undefined
        },
        include: { category: true },
      });
      actionType = `CREATE_ARTICLE_${article.status}`;
    }

    // Do not create an immutable revision snapshot for autosaves
    if (!data.isAutosave) {
      await db.articleRevision.create({
        data: {
          articleId: article.id,
          userId: user.id,
          title: article.title,
          deck: article.deck,
          contentHtml: article.contentHtml,
          contentJson: article.contentJson ? JSON.parse(JSON.stringify(article.contentJson)) : null,
          notes: data.notes || null,
          statusChange: null,
        }
      });
    }

    await logAudit(actionType, "Article", article.id, { title: article.title, status: article.status });

    // Revalidate relevant pages
    try {
      revalidatePath("/", "layout");
      revalidatePath("/admin", "layout");
      revalidatePath(`/article/${article.slug}`, "page");
      revalidatePath("/sitemap.xml");
    } catch (revalError) {
      console.warn(">>> [SERVER] Revalidation error:", revalError);
    }

    return { success: true, article };
  } catch (error: any) {
    return handleServerError(error, "Failed to save article");
  }
}


// ---------------------------------------------------------------------------
// Revision restore
// ---------------------------------------------------------------------------
// Snapshots have been written on every non-autosave save since the beginning,
// carrying the full title/deck/contentHtml/contentJson. Nothing ever read them
// back. So the history was visible but inert: an editor could see that a good
// version existed three saves ago and had no way to return to it.
//
// Restore is deliberately NOT a rollback that erases what came after. It copies
// the old snapshot forward into the live article and writes a new revision for
// the restore itself, so the timeline keeps growing in one direction and the
// version being replaced stays recoverable. A destructive rollback would make
// a misclick unrecoverable, which is the opposite of what version history is
// for.

export async function restoreRevision(revisionId: string) {
  const user = await getCurrentUser();
  if (!user) return { success: false, error: "Unauthorized" };

  try {
    const revision = await db.articleRevision.findUnique({
      where: { id: revisionId },
      include: {
        article: {
          select: { id: true, slug: true, title: true, status: true, authorId: true },
        },
      },
    });

    if (!revision) return { success: false, error: "Revision not found" };

    const article = revision.article;

    // Restoring rewrites the live article body, so it needs edit rights on that
    // specific article -- not merely the right to view its history. canEditArticle
    // resolves ownership too, so an author can roll back their own draft while
    // being unable to touch anyone else's.
    const policy = canEditArticle(
      { id: user.id, role: user.role, authorId: user.authorId },
      { id: article.id, authorId: article.authorId }
    );
    if (!policy.success) {
      return { success: false, error: policy.error || "Unauthorized" };
    }

    // A published article is live. Silently swapping its body from history is
    // a content change readers see immediately, and the workflow has explicit
    // transitions for taking something off the site. Refuse rather than
    // surprise: unpublish first, restore, then republish.
    if (article.status === "PUBLISHED") {
      return {
        success: false,
        error:
          "This article is published. Unpublish it before restoring an earlier version, so the change is reviewed before readers see it.",
      };
    }

    // Re-sanitize on the way back in. The snapshot was sanitized when written,
    // but the allowlist may have tightened since, and trusting stored HTML
    // because it was once clean is how an old payload survives a policy change.
    const restoredHtml = sanitizeArticleHtml(revision.contentHtml);

    await db.$transaction(async (tx) => {
      await tx.article.update({
        where: { id: article.id },
        data: {
          title: revision.title ?? article.title,
          deck: revision.deck,
          contentHtml: restoredHtml,
          contentJson: revision.contentJson
            ? JSON.parse(JSON.stringify(revision.contentJson))
            : null,
        },
      });

      // The restore is itself a revision. Without this the timeline would show
      // the article changing with no entry explaining why.
      await tx.articleRevision.create({
        data: {
          articleId: article.id,
          userId: user.id,
          title: revision.title ?? article.title,
          deck: revision.deck,
          contentHtml: restoredHtml,
          contentJson: revision.contentJson
            ? JSON.parse(JSON.stringify(revision.contentJson))
            : null,
          notes: `Restored the version saved on ${new Date(
            revision.createdAt
          ).toLocaleString("en-US", {
            year: "numeric",
            month: "short",
            day: "numeric",
            hour: "numeric",
            minute: "2-digit",
          })}.`,
          statusChange: null,
        },
      });
    });

    await logAudit("RESTORE_REVISION", "Article", article.id, {
      revisionId,
      revisionCreatedAt: revision.createdAt,
      title: revision.title,
    });

    revalidatePath(`/admin/articles/${article.id}`);
    revalidatePath(`/admin/editor/${article.id}`);
    revalidatePath("/admin/articles");

    return { success: true, articleId: article.id };
  } catch (error: unknown) {
    return handleServerError(error, "Failed to restore revision");
  }
}

export async function incrementArticleView(id: string) {
  try {
    const reqHeaders = await headers();
    const ip = getClientIp(reqHeaders);
    const rl = await checkRateLimit("view", `${id}:${ip}`, { limit: 5, windowMs: 60 * 60 * 1000 });

    if (!rl.allowed) {
      return { success: false };
    }

    await db.article.update({
      where: { id },
      data: { views: { increment: 1 } },
    });
    // Deliberately avoiding revalidatePath here to prevent cache churn on every view.
    return { success: true };
  } catch (error) {
    return handleServerError(error, "Failed to increment view");
  }
}

"use server";

import { z } from "zod";
import { db } from "@/lib/db";
import { createHash } from "crypto";
import { headers } from "next/headers";
import { checkRateLimit, getClientIp } from "@/lib/rateLimit";
import { getCurrentUser } from "@/lib/auth";
import { hasRequiredRole } from "@/lib/permissions";
import { Role, CommentStatus } from "@prisma/client";
import { revalidatePath } from "next/cache";

// ─── Safe public shape returned to readers ──────────────────────────────────
export interface PublicComment {
  id: string;
  displayName: string;
  emailHash: string; // for Gravatar — safe to expose
  body: string;
  createdAt: string;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────
function sha256(input: string): string {
  return createHash("sha256").update(input.toLowerCase().trim()).digest("hex");
}

const nameSchema = z.string().min(1).max(60).trim();
const emailSchema = z.string().email().max(320).toLowerCase().trim();
const bodySchema = z.string().min(10).max(1200).trim();

// ─── Get approved comments for an article ───────────────────────────────────
export async function getComments(articleSlug: string): Promise<PublicComment[]> {
  if (!articleSlug || typeof articleSlug !== "string") return [];

  const comments = await db.comment.findMany({
    where: { articleSlug, status: "APPROVED" },
    orderBy: { createdAt: "asc" },
    select: { id: true, displayName: true, emailHash: true, body: true, createdAt: true },
  });

  return comments.map((c) => ({
    ...c,
    createdAt: c.createdAt.toISOString(),
  }));
}

// ─── Get comment count for an article (for SSR display) ─────────────────────
export async function getCommentCount(articleSlug: string): Promise<number> {
  if (!articleSlug || typeof articleSlug !== "string") return 0;
  return db.comment.count({ where: { articleSlug, status: "APPROVED" } });
}

// ─── Post a comment ──────────────────────────────────────────────────────────
export async function postComment(
  articleSlug: string,
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  // Rate limit: 5 comments per 10 minutes per IP
  const hdrs = await headers();
  const ip = getClientIp(hdrs);
  const rl = await checkRateLimit("comment", ip, { limit: 5, windowMs: 10 * 60 * 1000 });
  if (!rl.allowed) {
    return { success: false, error: "Too many submissions. Please wait a few minutes and try again." };
  }

  const rawName = formData.get("name");
  const rawEmail = formData.get("email");
  const rawBody = formData.get("comment");

  const nameResult = nameSchema.safeParse(rawName);
  const emailResult = emailSchema.safeParse(rawEmail);
  const bodyResult = bodySchema.safeParse(rawBody);

  if (!nameResult.success) return { success: false, error: "Name is required (max 60 characters)." };
  if (!emailResult.success) return { success: false, error: "A valid email address is required." };
  if (!bodyResult.success) {
    return {
      success: false,
      error: bodyResult.error.issues[0]?.message?.includes("too_small")
        ? "Comment must be at least 10 characters."
        : "Comment must be 1200 characters or fewer.",
    };
  }

  // Find article by slug to get its ID
  const article = await db.article.findUnique({
    where: { slug: articleSlug },
    select: { id: true, status: true },
  });

  if (!article || article.status !== "PUBLISHED") {
    return { success: false, error: "Article not found or not published." };
  }

  const emailHash = sha256(emailResult.data);
  const ipHash = sha256(ip);
  const ua = hdrs.get("user-agent") || undefined;

  try {
    await db.comment.create({
      data: {
        articleId: article.id,
        articleSlug,
        displayName: nameResult.data,
        emailHash,
        body: bodyResult.data,
        status: "PENDING",
        ipHash,
        userAgent: ua?.slice(0, 500) ?? null,
      },
    });

    return { success: true };
  } catch (error: any) {
    console.error("[comments] postComment error:", error);
    return { success: false, error: "Failed to submit comment. Please try again." };
  }
}

// ─── Moderate a comment (MODERATOR+ only) ────────────────────────────────────
export async function moderateComment(
  commentId: string,
  action: "APPROVED" | "REJECTED" | "SPAM",
  note?: string
): Promise<{ success: boolean; error?: string }> {
  const user = await getCurrentUser();
  if (!user) return { success: false, error: "Unauthenticated" };

  const canModerate = hasRequiredRole(user.role as Role, "MODERATOR");
  if (!canModerate) return { success: false, error: "Insufficient permissions to moderate comments." };

  if (!commentId || typeof commentId !== "string") {
    return { success: false, error: "Invalid comment ID." };
  }

  const validActions: CommentStatus[] = ["APPROVED", "REJECTED", "SPAM"];
  if (!validActions.includes(action as CommentStatus)) {
    return { success: false, error: "Invalid moderation action." };
  }

  try {
    const comment = await db.comment.findUnique({ where: { id: commentId } });
    if (!comment) return { success: false, error: "Comment not found." };

    await db.comment.update({
      where: { id: commentId },
      data: {
        status: action as CommentStatus,
        moderatorId: user.id,
        moderatorNote: note?.trim().slice(0, 500) || null,
      },
    });

    revalidatePath(`/article/${comment.articleSlug}`, "page");
    return { success: true };
  } catch (error: any) {
    console.error("[comments] moderateComment error:", error);
    return { success: false, error: "Failed to update comment status." };
  }
}

// ─── Get pending comments queue (MODERATOR+ only) ────────────────────────────
export async function getPendingComments(page = 1) {
  const user = await getCurrentUser();
  if (!user) return { success: false, error: "Unauthenticated", comments: [] };

  const canModerate = hasRequiredRole(user.role as Role, "MODERATOR");
  if (!canModerate) return { success: false, error: "Insufficient permissions.", comments: [] };

  const perPage = 20;
  const skip = (page - 1) * perPage;

  const [comments, total] = await Promise.all([
    db.comment.findMany({
      where: { status: { in: ["PENDING", "SPAM"] } },
      orderBy: { createdAt: "desc" },
      skip,
      take: perPage,
      select: {
        id: true,
        articleSlug: true,
        displayName: true,
        body: true,
        status: true,
        ipHash: true,
        createdAt: true,
        moderatorNote: true,
        moderator: { select: { name: true } },
      },
    }),
    db.comment.count({ where: { status: { in: ["PENDING", "SPAM"] } } }),
  ]);

  return { success: true, comments, total, pages: Math.ceil(total / perPage) };
}

"use server";

import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { canAssignRole, canManageUser, hasRequiredRole } from "@/lib/permissions";
import crypto from "crypto";
import { sendInvitationEmail } from "@/lib/email";
import bcrypt from "bcryptjs";
import { Role } from "@prisma/client";

async function logAudit(action: string, entityType: string, entityId?: string, details?: any) {
  try {
    const user = await getCurrentUser();
    await db.auditLog.create({
      data: {
        userId: user?.id || null,
        action,
        entityType,
        entityId,
        details,
      }
    });
  } catch (e) {
    console.error("Failed to log audit event:", e);
  }
}

export async function inviteUser(formData: FormData) {
  try {
    const admin = await getCurrentUser();
    if (!admin) return { success: false, error: "Unauthenticated" };
    const email = formData.get("email") as string;
    const role = formData.get("role") as string;
    if (!email || !role) {
      return { success: false, error: "Email and role are required." };
    }

    const assignPolicy = canAssignRole(admin.role as Role, role as Role);
    if (!assignPolicy.success) return assignPolicy;

    // Check if user exists
    const existingUser = await db.user.findUnique({ where: { email } });
    if (existingUser) {
      return { success: false, error: "A user with this email already exists." };
    }

    // Generate secure token
    const token = crypto.randomBytes(32).toString("hex");
    const expires = new Date(Date.now() + 48 * 60 * 60 * 1000); // 48 hours

    // Create or update pending invitation
    const invitation = await db.invitation.upsert({
      where: { email },
      update: {
        token,
        expires,
        role: role as Role,
        status: "PENDING",
        invitedBy: admin.id,
      },
      create: {
        email,
        token,
        expires,
        role: role as Role,
        status: "PENDING",
        invitedBy: admin.id,
      },
    });

    const baseUrl = process.env.NODE_ENV === "production" ? "https://admin.xsypher.com" : (process.env.NEXT_PUBLIC_SITE_URL || "http://localhost:3000");
    const inviteUrl = `${baseUrl}/invite/${token}`;

    const emailResult = await sendInvitationEmail({ to: email, role, inviteUrl });

    await logAudit("INVITE_USER", "Invitation", invitation.id, { email, role });

    if (!emailResult.success) {
      return { success: true, inviteUrl, warning: "Failed to send email. " + emailResult.error };
    }

    return { success: true, inviteUrl };
  } catch (error: any) {
    console.error("Invite error:", error);
    return { success: false, error: error.message || "An error occurred." };
  }
}

export async function revokeInvitation(id: string) {
  try {
    const admin = await getCurrentUser();
    if (!admin) return { success: false, error: "Unauthenticated" };

    const invitationToRevoke = await db.invitation.findUnique({ where: { id } });
    if (!invitationToRevoke) return { success: false, error: "Invitation not found" };

    const managePolicy = canManageUser(admin.role as Role, invitationToRevoke.role as Role);
    if (!managePolicy.success) return managePolicy;

    const invitation = await db.invitation.update({
      where: { id },
      data: { status: "REVOKED" },
    });

    await logAudit("REVOKE_INVITATION", "Invitation", id, { email: invitation.email });
    return { success: true };
  } catch (error: any) {
    console.error("Revoke error:", error);
    return { success: false, error: "Failed to revoke invitation." };
  }
}

export async function acceptInvitation(token: string, formData: FormData) {
  try {
    const name = formData.get("name") as string;
    const password = formData.get("password") as string;

    if (!name || !password || password.length < 8) {
      return { success: false, error: "Valid name and password (min 8 chars) required." };
    }

    const invitation = await db.invitation.findUnique({ where: { token } });
    if (!invitation || invitation.status !== "PENDING" || invitation.expires < new Date()) {
      return { success: false, error: "Invalid or expired invitation." };
    }

    const hashedPassword = await bcrypt.hash(password, 10);

    const user = await db.user.create({
      data: {
        email: invitation.email,
        name,
        password: hashedPassword,
        role: invitation.role,
      }
    });

    await db.invitation.update({
      where: { id: invitation.id },
      data: { status: "ACCEPTED" },
    });

    await db.auditLog.create({
      data: {
        userId: user.id,
        action: "ACCEPT_INVITATION",
        entityType: "User",
        entityId: user.id,
        details: { role: user.role }
      }
    });

    return { success: true };
  } catch (error: any) {
    console.error("Accept invite error:", error);
    return { success: false, error: "Failed to accept invitation." };
  }
}

"use server";

import { z } from "zod";
import { db } from "@/lib/db";
import { headers } from "next/headers";
import { checkRateLimit, getClientIp } from "@/lib/rateLimit";

const emailSchema = z.string().email().max(320).transform((e) => e.toLowerCase().trim());

export async function subscribeNewsletter(
  email: string,
  source: string = "HOMEPAGE"
) {
  // Rate limit: 3 signups per 10 minutes per IP
  const hdrs = await headers();
  const ip = getClientIp(hdrs);
  const rl = await checkRateLimit("newsletter", ip, { limit: 3, windowMs: 10 * 60 * 1000 });
  if (!rl.allowed) {
    return { success: false, error: "Too many requests. Please try again later." };
  }

  const parsed = emailSchema.safeParse(email);
  if (!parsed.success) {
    return { success: false, error: "Please enter a valid email address." };
  }
  const normalizedEmail = parsed.data;

  try {
    const existing = await db.subscriber.findUnique({ where: { email: normalizedEmail } });

    if (existing) {
      if (existing.status === "ACTIVE") {
        return { success: false, code: "ALREADY_SUBSCRIBED", error: "This email is already subscribed." };
      }
      // Re-subscribe: reset status to ACTIVE and refresh consent timestamp
      await db.subscriber.update({
        where: { id: existing.id },
        data: { status: "ACTIVE", consentAt: new Date(), source, updatedAt: new Date() },
      });
      return { success: true, message: "Welcome back — you're back on the list." };
    }

    await db.subscriber.create({
      data: {
        email: normalizedEmail,
        status: "ACTIVE",
        source,
        consentAt: new Date(),
      },
    });

    return { success: true, message: "You're on the list." };
  } catch (error: any) {
    console.error("[newsletter] subscribeNewsletter error:", error);
    return { success: false, error: "Failed to process subscription. Please try again." };
  }
}

export async function unsubscribeByToken(token: string) {
  if (!token || typeof token !== "string" || token.length > 128) {
    return { success: false, error: "Invalid unsubscribe link." };
  }

  try {
    const subscriber = await db.subscriber.findUnique({ where: { unsubscribeToken: token } });

    if (!subscriber) {
      return { success: false, error: "This unsubscribe link is invalid or has already been used." };
    }

    if (subscriber.status === "UNSUBSCRIBED") {
      return { success: true, message: "You are already unsubscribed.", alreadyDone: true };
    }

    await db.subscriber.update({
      where: { id: subscriber.id },
      data: { status: "UNSUBSCRIBED" },
    });

    return { success: true, message: "You have been unsubscribed successfully." };
  } catch (error: any) {
    console.error("[newsletter] unsubscribeByToken error:", error);
    return { success: false, error: "Failed to process unsubscribe request." };
  }
}

"use server";

import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { authorize } from "@/lib/capabilities";
import type { Role } from "@prisma/client";
import { revalidatePath } from "next/cache";
import { sanitizeBioHtml, isValidSafeUrl, ALLOWED_MEDIA_DOMAINS } from "@/lib/sanitize";

export async function updateProfile(data: any) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      throw new Error("Unauthorized");
    }

    // Editing someone else's profile.
    //
    // data.targetUserId is a request, not an instruction: the capability is
    // checked against the *actor's* role read from the database, never from the
    // session or the payload. Without this the action always wrote to the
    // caller's own authorId, so an owner had no way to correct another user's
    // name or byline.
    //
    // author.manage.all is the same capability that gates /admin/authors, so
    // the UI and the server agree on who may do this.
    const requestedTargetId: string | undefined =
      typeof data?.targetUserId === "string" && data.targetUserId.trim()
        ? data.targetUserId.trim()
        : undefined;

    const actor = await db.user.findUnique({ where: { id: user.id } });
    if (!actor) {
      throw new Error("User not found in database.");
    }

    const isEditingOther = Boolean(requestedTargetId && requestedTargetId !== actor.id);

    if (isEditingOther && !authorize(actor.role as Role, "author.manage.all")) {
      return { success: false, error: "You do not have permission to edit another user's profile." };
    }

    const dbUser = isEditingOther
      ? await db.user.findUnique({ where: { id: requestedTargetId! } })
      : actor;

    if (!dbUser) {
      throw new Error("User not found in database.");
    }

    const { name, headline, role, overview, bio, avatar, location, website, email, socialLinks, expertise, verifiedTitle, disclosure, publicContact, slug: submittedSlug, pgpPublicKey } = data;

    // Generate base slug
    const baseSlug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '') || `user-${dbUser.id.substring(0, 6)}`;

    // Only OWNER and ADMIN can edit `role` and `verifiedTitle`
    // Checked against the actor, not the profile being edited -- otherwise
    // editing an admin's profile would confer admin privileges on the edit.
    const isEditorialAdmin = authorize(actor.role as Role, "user.manage");
    let finalRole = role;
    let finalVerifiedTitle = verifiedTitle;

    // Validate avatar URL against trusted domains
    if (avatar && !isValidSafeUrl(avatar, ALLOWED_MEDIA_DOMAINS)) {
      return { success: false, error: "Avatar URL is invalid or from an unapproved domain." };
    }

    // Validate website URL
    if (website && !isValidSafeUrl(website)) {
      return { success: false, error: "Website URL must be a valid HTTP or HTTPS link." };
    }

    // Sanitize bio
    const safeBio = sanitizeBioHtml(bio);

    // Validate social links
    const safeSocialLinks = socialLinks;
    if (socialLinks) {
      let parsedLinks = [];
      try {
        parsedLinks = typeof socialLinks === "string" ? JSON.parse(socialLinks) : socialLinks;
        if (Array.isArray(parsedLinks)) {
          for (const link of parsedLinks) {
            if (link.url && !isValidSafeUrl(link.url)) {
              return { success: false, error: `Invalid social link URL: ${link.url}` };
            }
          }
        }
      } catch (e) {
        // Just let it pass if not parsable array, though realistically it shouldn't happen
      }
    }

    // If user already has an author, manage slug history
    let finalSlug = baseSlug;
    let updatedPreviousSlugs: string[] = [];

    if (dbUser.authorId) {
      const existing = await db.author.findUnique({ where: { id: dbUser.authorId } });
      if (existing) {
        if (!isEditorialAdmin && actor.role !== "AUTHOR") {
           // Let's assume standard authors might be allowed to change name but admins can change slug?
           // The prompt says "Do not break current author URLs... handle slug changes through a redirect strategy"
           // Let's allow users to submit a slug or we use baseSlug, but we enforce uniqueness and redirect
        }

        finalSlug = submittedSlug || existing.slug;
        if (!finalRole && !isEditorialAdmin) finalRole = existing.role;
        if (finalVerifiedTitle === undefined && !isEditorialAdmin) finalVerifiedTitle = existing.verifiedTitle;

        const currentPreviousSlugs = existing.previousSlugs || [];
        updatedPreviousSlugs = existing.slug !== finalSlug 
          ? Array.from(new Set([...currentPreviousSlugs, existing.slug]))
          : currentPreviousSlugs;
      }
    } else {
      finalSlug = submittedSlug || baseSlug;
    }

    const author = await db.author.upsert({
      where: { id: dbUser.authorId || 'non-existent-id' },
      update: { 
        slug: finalSlug, previousSlugs: updatedPreviousSlugs,
        name, headline, role: isEditorialAdmin ? finalRole : undefined, 
        overview, bio: safeBio, avatar, location, website, email, socialLinks: safeSocialLinks,
        expertise, verifiedTitle: isEditorialAdmin ? finalVerifiedTitle : undefined,
        disclosure, publicContact 
      },
      create: { 
        slug: finalSlug, name, headline, role: isEditorialAdmin ? finalRole : null, 
        overview, bio: safeBio, avatar, location, website, email, socialLinks: safeSocialLinks,
        expertise, verifiedTitle: isEditorialAdmin ? (finalVerifiedTitle || false) : false,
        disclosure, publicContact: publicContact !== undefined ? publicContact : true 
      },
    });

    if (!dbUser.authorId || dbUser.name !== name || pgpPublicKey !== undefined) {
      await db.user.update({
        // dbUser, not the actor: when an owner edits someone else's profile
        // the author record must attach to that user's account.
        where: { id: dbUser.id },
        data: { 
          authorId: author.id, 
          name, 
          ...(pgpPublicKey !== undefined ? { pgpPublicKey } : {})
        },
      });
    }

    revalidatePath('/admin/settings');
    revalidatePath('/admin');
    revalidatePath(`/author/${author.slug}`);

    return { success: true, slug: author.slug };
  } catch (error: any) {
    console.error("updateProfile error:", error);
    return { success: false, error: error.message || "Failed to update profile" };
  }
}

// ---------------------------------------------------------------------------
// Notification preferences
// ---------------------------------------------------------------------------
// The settings form has had these three toggles since it was written, but
// handlePrefsSubmit was a setTimeout that showed "(Mock)" and discarded the
// change. Now that notifications actually send email, a toggle that does not
// persist is worse than no toggle: someone turns alerts off, is told it worked,
// and keeps receiving mail.

export type NotificationPrefsInput = {
  emailAlerts?: boolean;
  weeklyDigest?: boolean;
  reviewUpdates?: boolean;
};

export async function updateNotificationPrefs(prefs: NotificationPrefsInput) {
  const user = await getCurrentUser();
  if (!user) return { success: false, error: "Unauthorized" };

  try {
    // Whitelist and coerce rather than storing the payload as-is. This lands in
    // a Json column, so an unvalidated object would let a client persist
    // arbitrary keys into the user record.
    const clean = {
      emailAlerts: prefs.emailAlerts !== false,
      weeklyDigest: prefs.weeklyDigest === true,
      reviewUpdates: prefs.reviewUpdates !== false,
    };

    await db.user.update({
      where: { id: user.id },
      data: { notificationPrefs: clean },
    });

    revalidatePath("/admin/settings");
    return { success: true, prefs: clean };
  } catch (error: unknown) {
    const message =
      error instanceof Error ? error.message : "Failed to update preferences";
    return { success: false, error: message };
  }
}

"use server";

import { db } from "@/lib/db";
import bcrypt from "bcryptjs";
import { Prisma } from "@prisma/client";
import { handleServerError } from "@/lib/errors";

export async function setupOwner(email: string, password: string, name: string) {
  if (!email || !password || password.length < 8) {
    return { error: "Invalid email or password (min 8 characters)." };
  }

  try {
    const hashedPassword = await bcrypt.hash(password, 10);

    const user = await db.$transaction(async (tx) => {
      const userCount = await tx.user.count();

      if (userCount > 0) {
        throw new Error("Setup has already been completed.");
      }

      return await tx.user.create({
        data: {
          email,
          name,
          password: hashedPassword,
          role: "OWNER",
        }
      });
    }, {
      isolationLevel: Prisma.TransactionIsolationLevel.Serializable
    });

    return { success: true, userId: user.id };
  } catch (error: any) {
    const isExpected = error.message === "Setup has already been completed.";
    return handleServerError(error, isExpected ? error.message : "Failed to create owner.");
  }
}

"use server";

import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { canManageUser, canAssignRole } from "@/lib/permissions";
import { Role } from "@prisma/client";
import { revalidatePath } from "next/cache";
import { handleServerError } from "@/lib/errors";

export async function updateUserRole(userId: string, newRole: Role) {
  try {
    const admin = await getCurrentUser();
    if (!admin) return { success: false, error: "Unauthenticated" };

    const assignPolicy = canAssignRole(admin.role as Role, newRole);
    if (!assignPolicy.success) return assignPolicy;

    const userToUpdate = await db.user.findUnique({ where: { id: userId } });
    if (!userToUpdate) return { success: false, error: "User not found" };

    if (admin.id !== userId) {
      const managePolicy = canManageUser(admin.role as Role, userToUpdate.role as Role);
      if (!managePolicy.success) return managePolicy;
    }

    await db.user.update({
      where: { id: userId },
      data: { 
        role: newRole,
        sessionVersion: { increment: 1 } 
      }
    });

    await db.auditLog.create({
      data: {
        userId: admin.id,
        action: "UPDATE_USER_ROLE",
        entityType: "User",
        entityId: userId,
        details: { newRole }
      }
    });

    revalidatePath("/admin/users");
    return { success: true };
  } catch (error: any) {
    return handleServerError(error, "Failed to update user role");
  }
}

export async function deleteUser(userId: string) {
  try {
    const admin = await getCurrentUser();
    if (!admin) return { success: false, error: "Unauthenticated" };

    if (admin.id === userId) {
      return { success: false, error: "Cannot delete yourself." };
    }

    const userToDelete = await db.user.findUnique({ where: { id: userId } });
    if (!userToDelete) return { success: false, error: "User not found" };

    const managePolicy = canManageUser(admin.role as Role, userToDelete.role as Role);
    if (!managePolicy.success) return managePolicy;

    await db.user.delete({
      where: { id: userId }
    });

    await db.auditLog.create({
      data: {
        userId: admin.id,
        action: "DELETE_USER",
        entityType: "User",
        entityId: userId,
      }
    });

    revalidatePath("/admin/users");
    return { success: true };
  } catch (error: any) {
    return handleServerError(error, "Failed to delete user");
  }
}

"use server";

import { db } from "@/lib/db";
import { getActor } from "@/lib/auth";
import { authorize, ROLE_CAPABILITIES } from "@/lib/capabilities";
import { ArticleStatus, Role, Prisma } from "@prisma/client";

const REVIEWER_ROLES = (Object.keys(ROLE_CAPABILITIES) as Role[]).filter(role => 
  authorize(role, "article.review")
);
import { validateTransition, TRANSITIONS, ArticleForTransition } from "@/lib/workflow";
import {
  notifySubmitted,
  notifyApproved,
  notifyChangesRequested,
  notifyRejected,
  notifyPublished,
  notifyUnpublished,
} from "@/lib/notifications";
import { revalidatePath, updateTag } from "next/cache";
import { CACHE_TAGS, articleTag, articleMutationTags } from "@/lib/cache-tags";

export type ActionResponse<T = any> =
  | { ok: true; data?: T; updatedAt?: string }
  | { ok: false; code: "UNAUTHENTICATED" | "FORBIDDEN" | "NOT_FOUND" | "CONFLICT" | "VALIDATION" | "RATE_LIMITED" | "SERVER"; message: string };

// ──────────────────────────────────────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────────────────────────────────────

async function getArticle(id: string) {
  return await db.article.findUnique({
    where: { id },
    select: {
      id: true,
      status: true,
      authorId: true,
      reviewedById: true,
      title: true,
      slug: true,
      categoryId: true,
      category: { select: { slug: true } },
      authorModel: { select: { slug: true } },
      deck: true,
      contentHtml: true,
    }
  });
}

async function checkSelfReviewGuard(article: any, actor: any) {
  if (article.authorId && actor.authorId && article.authorId === actor.authorId) {
    const activeReviewersCount = await db.user.count({
      where: { isActive: true, role: { in: REVIEWER_ROLES } }
    });
    if (activeReviewersCount > 1) {
      return { ok: false, code: "FORBIDDEN", message: "A reviewer cannot decide on their own article. Please ask another editor to review it." };
    }
    return { ok: true, isSelfReview: true };
  }
  return { ok: true, isSelfReview: false };
}

// ──────────────────────────────────────────────────────────────────────────────
// Review Claiming (Not strict transitions, but workflow operations)
// ──────────────────────────────────────────────────────────────────────────────

export async function claimReview(id: string): Promise<ActionResponse> {
  const actor = await getActor();
  if (!actor) return { ok: false, code: "UNAUTHENTICATED", message: "Sign in required." };
  if (!authorize(actor.role, "article.review")) {
    return { ok: false, code: "FORBIDDEN", message: "Insufficient permissions to claim reviews." };
  }

  try {
    const article = await getArticle(id);
    if (!article) return { ok: false, code: "NOT_FOUND", message: "Article not found." };
    if (article.reviewedById && article.reviewedById !== actor.id) {
      return { ok: false, code: "CONFLICT", message: "Article is already claimed by another reviewer." };
    }

    const { count } = await db.article.updateMany({
      where: { id, reviewedById: null, status: article.status },
      data: { reviewedById: actor.id }
    });

    if (count === 0) {
      return { ok: false, code: "CONFLICT", message: "Article was claimed by another reviewer just now." };
    }

    await db.auditLog.create({
      data: { userId: actor.id, action: "CLAIM_REVIEW", entityType: "Article", entityId: id }
    });

    revalidatePath(`/admin/review`);
    revalidatePath(`/admin/review/${id}`);
    return { ok: true };
  } catch (e: any) {
    return { ok: false, code: "SERVER", message: e.message };
  }
}

export async function releaseReview(id: string): Promise<ActionResponse> {
  const actor = await getActor();
  if (!actor) return { ok: false, code: "UNAUTHENTICATED", message: "Sign in required." };

  const article = await getArticle(id);
  if (!article) return { ok: false, code: "NOT_FOUND", message: "Article not found." };

  if (article.reviewedById !== actor.id) {
    return { ok: false, code: "FORBIDDEN", message: "You cannot release an article you have not claimed." };
  }

  await db.article.update({
    where: { id },
    data: { reviewedById: null }
  });

  await db.auditLog.create({
    data: { userId: actor.id, action: "RELEASE_REVIEW", entityType: "Article", entityId: id }
  });

  revalidatePath(`/admin/review`);
  revalidatePath(`/admin/review/${id}`);
  return { ok: true };
}

export async function takeOverReview(id: string, confirm: boolean): Promise<ActionResponse> {
  const actor = await getActor();
  if (!actor) return { ok: false, code: "UNAUTHENTICATED", message: "Sign in required." };
  if (!authorize(actor.role, "article.review")) {
    return { ok: false, code: "FORBIDDEN", message: "Insufficient permissions." };
  }

  const article = await getArticle(id);
  if (!article) return { ok: false, code: "NOT_FOUND", message: "Article not found." };

  if (!article.reviewedById) {
    return { ok: false, code: "VALIDATION", message: "This article is unclaimed. Please use the ordinary claim action." };
  }

  if (article.reviewedById === actor.id) {
    return { ok: false, code: "VALIDATION", message: "You are already the reviewer of this article." };
  }

  if (!confirm) {
    return { ok: false, code: "VALIDATION", message: "You must explicitly confirm to take over an article." };
  }

  await db.article.update({
    where: { id },
    data: { reviewedById: actor.id }
  });

  await db.auditLog.create({
    data: { userId: actor.id, action: "TAKEOVER_REVIEW", entityType: "Article", entityId: id, details: { previousReviewerId: article.reviewedById, newReviewerId: actor.id } }
  });

  revalidatePath(`/admin/review`);
  revalidatePath(`/admin/review/${id}`);
  return { ok: true };
}

// ──────────────────────────────────────────────────────────────────────────────
// Transitions
// ──────────────────────────────────────────────────────────────────────────────

/**
 * Invalidate every public route whose content depends on this article.
 *
 * The public pages are cached with a revalidate window now, so these calls are
 * what makes an editorial change appear immediately instead of up to five
 * minutes later. Previously each transition inlined its own list and they had
 * drifted: none of them invalidated /latest (only the scheduler did) or the
 * author's profile page, so unpublishing an article left it visible on both
 * until the timer expired. Keeping the list in one function is what stops that
 * drift from recurring.
 */
function revalidateArticleRoutes(article: {
  slug: string;
  category?: { slug: string } | null;
  authorModel?: { slug: string } | null;
}) {
  // Tags, not revalidatePath("/", "layout").
  //
  // That call was the broadest invalidation Next.js offers: it drops every
  // route under the root layout, so publishing one story discarded the
  // homepage, /latest, all thirteen categories, every tag page, every author
  // page and every other article. On a title that ships several stories an
  // hour the public cache was rarely warm.
  //
  // articleMutationTags names what actually changed -- the article listings,
  // this article, its category, its author -- and leaves everything else
  // cached.
  for (const tag of articleMutationTags(article)) {
    updateTag(tag);
  }

  // The article's own route is still invalidated by path. Its page component
  // queries the article directly rather than through a tagged helper, because
  // it needs the body columns the card select deliberately omits.
  revalidatePath(`/article/${article.slug}`, "page");

  // Revalidate the sitemap so search engines immediately see the new/updated URL.
  revalidatePath("/sitemap.xml");
}

async function executeTransition(
  id: string,
  to: ArticleStatus,
  actionFn: (article: any, actor: any) => Promise<ActionResponse>
): Promise<ActionResponse> {
  const actor = await getActor();
  if (!actor) return { ok: false, code: "UNAUTHENTICATED", message: "Sign in required." };

  const article = await getArticle(id);
  if (!article) return { ok: false, code: "NOT_FOUND", message: "Article not found." };

  const validationError = validateTransition(article.status, to, actor, article);
  if (validationError) {
    return { ok: false, code: "FORBIDDEN", message: validationError };
  }

  const res = await actionFn(article, actor);
  if (res.ok) {
    const fresh = await db.article.findUnique({ where: { id }, select: { updatedAt: true } });
    if (fresh) {
      res.updatedAt = fresh.updatedAt.toISOString();
    }
  }
  return res;
}

export async function submitArticle(id: string): Promise<ActionResponse> {
  return executeTransition(id, "SUBMITTED", async (article, actor) => {
    if (!article.title?.trim()) {
      return { ok: false, code: "VALIDATION", message: "Title is required for submission." };
    }
    if (!article.deck || article.deck.trim().length < 10) {
      return { ok: false, code: "VALIDATION", message: "A short description (deck) of at least 10 characters is required." };
    }
    if (!article.categoryId) {
      return { ok: false, code: "VALIDATION", message: "Category is required." };
    }
    const textContent = article.contentHtml?.replace(/<[^>]+>/g, '').trim() || "";
    const wordCount = textContent.split(/\s+/).filter(Boolean).length;
    if (wordCount < 50) {
      return { ok: false, code: "VALIDATION", message: `Content must be at least 50 words. Currently: ${wordCount}` };
    }

    await db.$transaction(async (tx) => {
      await tx.article.update({
        where: { id },
        data: { 
          status: "SUBMITTED", 
          submittedAt: new Date(),
          submittedById: actor.id
        }
      });
      await tx.auditLog.create({
        data: { userId: actor.id, action: "SUBMIT_ARTICLE", entityType: "Article", entityId: id }
      });
    });

    await notifySubmitted(article, actor.id);

    revalidatePath(`/admin/articles`);
    revalidatePath(`/admin/review`);
    revalidatePath(`/admin/editor/${id}`);
    revalidatePath(`/admin`, `layout`);
    return { ok: true };
  });
}

export async function withdrawArticle(id: string): Promise<ActionResponse> {
  return executeTransition(id, "DRAFT", async (article, actor) => {
    await db.$transaction(async (tx) => {
      await tx.article.update({
        where: { id },
        data: { status: "DRAFT" }
      });
      await tx.auditLog.create({
        data: { userId: actor.id, action: "WITHDRAW_ARTICLE", entityType: "Article", entityId: id }
      });
    });

    revalidatePath(`/admin/articles`);
    revalidatePath(`/admin/editor/${id}`);
    return { ok: true };
  });
}

export async function approveArticle(id: string, notes?: string): Promise<ActionResponse> {
  return executeTransition(id, "APPROVED", async (article, actor) => {
    const selfGuard = await checkSelfReviewGuard(article, actor);
    if (!selfGuard.ok) return selfGuard as any;

    await db.$transaction(async (tx) => {
      await tx.article.update({
        where: { id },
        data: { 
          status: "APPROVED",
          approvedAt: new Date(),
          approvedById: actor.id,
          reviewedAt: new Date(),
          reviewedById: actor.id
        }
      });

      const passNumber = await tx.articleReview.count({ where: { articleId: id } }) + 1;

      await tx.articleReview.create({
        data: {
          articleId: id,
          reviewerId: actor.id,
          decision: "APPROVED",
          fromStatus: article.status,
          toStatus: "APPROVED",
          passNumber,
          reason: selfGuard.isSelfReview ? `[Self-review: no other reviewers] ${notes || ""}`.trim() : (notes || null)
        }
      });

      if (selfGuard.isSelfReview) {
        await tx.auditLog.create({
          data: { userId: actor.id, action: "SELF_REVIEW", entityType: "Article", entityId: id, details: { decision: "APPROVED", reason: "no other reviewers available" } }
        });
      }

      if (article.authorId) {
        const authorUser = await tx.user.findFirst({ where: { authorId: article.authorId } });
        if (authorUser && authorUser.id !== actor.id) {
          await tx.notification.create({
            data: {
              userId: authorUser.id,
              message: `"${article.title || 'Untitled'}" was approved.`,
              link: `/admin/editor/${id}`
            }
          });
        }
      }
    });

    await notifyApproved(article, actor.id);

    revalidatePath(`/admin/articles`);
    revalidatePath(`/admin/review`);
    revalidatePath(`/admin/editor/${id}`);
    return { ok: true };
  });
}

export async function requestChanges(id: string, reason: string): Promise<ActionResponse> {
  return executeTransition(id, "REVISION_REQUESTED", async (article, actor) => {
    if (!reason || reason.trim().length < 20) {
      return { ok: false, code: "VALIDATION", message: "A reason of at least 20 characters is required to request changes." };
    }

    const selfGuard = await checkSelfReviewGuard(article, actor);
    if (!selfGuard.ok) return selfGuard as any;

    await db.$transaction(async (tx) => {
      await tx.article.update({
        where: { id },
        data: { 
          status: "REVISION_REQUESTED",
          reviewedAt: new Date(),
          reviewedById: actor.id
        }
      });

      const passNumber = await tx.articleReview.count({ where: { articleId: id } }) + 1;

      await tx.articleReview.create({
        data: {
          articleId: id,
          reviewerId: actor.id,
          decision: "CHANGES_REQUESTED",
          fromStatus: article.status,
          toStatus: "REVISION_REQUESTED",
          passNumber,
          reason: selfGuard.isSelfReview ? `[Self-review: no other reviewers] ${reason}` : reason
        }
      });

      if (selfGuard.isSelfReview) {
        await tx.auditLog.create({
          data: { userId: actor.id, action: "SELF_REVIEW", entityType: "Article", entityId: id, details: { decision: "CHANGES_REQUESTED", reason: "no other reviewers available" } }
        });
      }

      if (article.authorId) {
        const authorUser = await tx.user.findFirst({ where: { authorId: article.authorId } });
        if (authorUser && authorUser.id !== actor.id) {
          await tx.notification.create({
            data: {
              userId: authorUser.id,
              message: `Changes requested on "${article.title || 'Untitled'}": ${reason.trim().slice(0, 140)}`,
              link: `/admin/editor/${id}`
            }
          });
        }
      }
    });

    await notifyChangesRequested(article, actor.id, reason);

    revalidatePath(`/admin/articles`);
    revalidatePath(`/admin/review`);
    revalidatePath(`/admin/editor/${id}`);
    return { ok: true };
  });
}

export async function rejectArticle(id: string, reason: string, reasonCode: string): Promise<ActionResponse> {
  return executeTransition(id, "REJECTED", async (article, actor) => {
    if (!reason || reason.trim().length < 20) {
      return { ok: false, code: "VALIDATION", message: "A reason of at least 20 characters is required for rejection." };
    }
    if (!reasonCode) {
      return { ok: false, code: "VALIDATION", message: "A reason code is required." };
    }

    const selfGuard = await checkSelfReviewGuard(article, actor);
    if (!selfGuard.ok) return selfGuard as any;

    await db.$transaction(async (tx) => {
      await tx.article.update({
        where: { id },
        data: { 
          status: "REJECTED",
          reviewedAt: new Date(),
          reviewedById: actor.id
        }
      });

      const passNumber = await tx.articleReview.count({ where: { articleId: id } }) + 1;

      await tx.articleReview.create({
        data: {
          articleId: id,
          reviewerId: actor.id,
          decision: "REJECTED",
          fromStatus: article.status,
          toStatus: "REJECTED",
          passNumber,
          reason: selfGuard.isSelfReview ? `[Self-review: no other reviewers] ${reason}` : reason,
          reasonCode
        }
      });

      if (selfGuard.isSelfReview) {
        await tx.auditLog.create({
          data: { userId: actor.id, action: "SELF_REVIEW", entityType: "Article", entityId: id, details: { decision: "REJECTED", reason: "no other reviewers available" } }
        });
      }

      if (article.authorId) {
        const authorUser = await tx.user.findFirst({ where: { authorId: article.authorId } });
        if (authorUser && authorUser.id !== actor.id) {
          await tx.notification.create({
            data: {
              userId: authorUser.id,
              message: `"${article.title || 'Untitled'}" was rejected: ${reason.trim().slice(0, 140)}`,
              link: `/admin/editor/${id}`
            }
          });
        }
      }
    });

    await notifyRejected(article, actor.id, reason);

    revalidatePath(`/admin/articles`);
    revalidatePath(`/admin/review`);
    revalidatePath(`/admin/editor/${id}`);
    return { ok: true };
  });
}

export async function reopenArticle(id: string): Promise<ActionResponse> {
