    await db.$transaction(async (tx) => {
      await tx.article.update({
        where: { id },
        data: { status: "DRAFT" }
      });
      await tx.auditLog.create({
        data: { userId: actor.id, action: "REOPEN_ARTICLE", entityType: "Article", entityId: id }
      });
