          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { useRouter, usePathname, useSearchParams } from "next/navigation";
import { Search, Filter, Download, Eye } from "lucide-react";
import Pagination from "@/components/console/Pagination";
import AuditLogDetailsDialog from "./AuditLogDetailsDialog";

interface AuditLog {
  id: string;
  userId: string | null;
  user: { name: string | null; email: string | null } | null;
  action: string;
  entityType: string;
  entityId: string | null;
  details: any;
  createdAt: string | Date;
}

interface AuditLogsClientProps {
  logs: AuditLog[];
  totalLogs: number;
  currentPage: number;
  itemsPerPage: number;
  /** Server render time, so relative ages do not depend on the client clock. */
  renderedAt: number;
}

export default function AuditLogsClient({
  logs,
  totalLogs,
  currentPage,
  itemsPerPage,
  renderedAt,
}: AuditLogsClientProps) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [searchQuery, setSearchQuery] = useState(searchParams.get("query") || "");
  const [selectedLog, setSelectedLog] = useState<AuditLog | null>(null);


  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const params = new URLSearchParams(searchParams.toString());
    if (searchQuery) {
      params.set("query", searchQuery);
    } else {
      params.delete("query");
    }
    params.set("page", "1");
    router.push(`${pathname}?${params.toString()}`);
  };

  const handleFilterChange = (key: string, value: string) => {
    const params = new URLSearchParams(searchParams.toString());
    if (value && value !== "All") {
      params.set(key, value);
    } else {
      params.delete(key);
    }
    params.set("page", "1");
    router.push(`${pathname}?${params.toString()}`);
  };

  const getActionBadgeStyle = (action: string) => {
    const act = action.toUpperCase();
    if (act.includes("PUBLISH") || act.includes("UPDATE") || act.includes("CREATE")) {
      return "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20";
    }
    if (act.includes("LOGIN") || act.includes("AUTH") || act.includes("PASSWORD")) {
      return "bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/20";
    }
    if (act.includes("DELETE") || act.includes("REVOKE") || act.includes("REMOVE")) {
      return "bg-bad/10 text-bad border-bad/20";
    }
    return "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20";
  };

  // `renderedAt` comes from the server as a prop rather than being read here.
  // Calling Date.now() while rendering a client component makes the
  // server-rendered string and the first client render disagree, which React
  // reports as a hydration mismatch, and it lets two rows a second apart show
  // different ages within one screen.
  const getRelativeTime = (date: string | Date) => {
    const diff = renderedAt - new Date(date).getTime();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (minutes < 1) return "Just now";
    if (minutes < 60) return `${minutes} min${minutes !== 1 ? "s" : ""} ago`;
    if (hours < 24) return `${hours} hr${hours !== 1 ? "s" : ""} ago`;
    if (days === 1) return "Yesterday";
    return `${days} days ago`;
  };

  const formatExactDate = (date: string | Date) => {
    return new Date(date).toISOString().replace("T", " ").slice(0, 19) + " UTC";
  };

  return (
    <>
      <div className="mb-6 flex flex-col md:flex-row gap-4 justify-between items-start md:items-center">
        <form onSubmit={handleSearch} className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-faint" />
          <input
            type="text"
            placeholder="Search actor, IP, or resource..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 py-2 text-sm bg-surface border border-line rounded-md focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent text-ink"
          />
        </form>

        <div className="flex items-center gap-3 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
          <div className="flex items-center bg-surface border border-line rounded-md px-3 py-1.5 h-[38px]">
            <Filter className="w-4 h-4 text-faint mr-2" />
            <select
              className="bg-transparent text-sm focus:outline-none text-ink-2 min-w-[120px]"
              value={searchParams.get("category") || "All"}
              onChange={(e) => handleFilterChange("category", e.target.value)}
            >
              <option value="All">All Events</option>
              <option value="Publishing">Publishing</option>
              <option value="Authentication">Authentication</option>
              <option value="User Management">User Management</option>
              <option value="System">System / Settings</option>
            </select>
          </div>

          <div className="flex items-center bg-surface border border-line rounded-md px-3 py-1.5 h-[38px]">
            <select
              className="bg-transparent text-sm focus:outline-none text-ink-2 min-w-[100px]"
              value={searchParams.get("dateRange") || "All Time"}
              onChange={(e) => handleFilterChange("dateRange", e.target.value)}
            >
              <option value="All Time">All Time</option>
              <option value="24h">Last 24 Hours</option>
              <option value="7d">Last 7 Days</option>
              <option value="30d">Last 30 Days</option>
            </select>
          </div>

          <button className="flex items-center justify-center h-[38px] px-3 gap-2 text-sm font-medium border border-line bg-surface text-ink-2 hover:bg-surface-2 rounded-md transition-colors whitespace-nowrap">
            <Download className="w-4 h-4" />
            Export Log
          </button>
        </div>
      </div>

      <div className="bg-surface border border-line rounded-xl shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[800px]">
            <thead>
              <tr className="border-b border-line bg-paper/50 dark:bg-surface/[0.02]">
                <th className="py-3 px-4 text-xs font-semibold text-muted uppercase tracking-wider w-[18%]">Timestamp</th>
                <th className="py-3 px-4 text-xs font-semibold text-muted uppercase tracking-wider w-[22%]">Actor</th>
                <th className="py-3 px-4 text-xs font-semibold text-muted uppercase tracking-wider w-[22%]">Action / Event</th>
                <th className="py-3 px-4 text-xs font-semibold text-muted uppercase tracking-wider w-[26%]">Resource / Target</th>
                <th className="py-3 px-4 text-xs font-semibold text-muted uppercase tracking-wider w-[12%] text-right">Details</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-line">
              {logs.length > 0 ? (
                logs.map((log) => (
                  <tr key={log.id} className="hover:bg-paper/80 dark:hover:bg-surface/5 transition-colors group">
                    <td className="py-3 px-4 align-top">
                      <div className="text-sm font-medium text-ink">
                        {getRelativeTime(log.createdAt)}
                      </div>
                      <div className="text-xs text-muted font-mono mt-0.5">
                        {formatExactDate(log.createdAt)}
                      </div>
                    </td>
                    <td className="py-3 px-4 align-top">
                      <div className="flex items-center gap-2">
                        <div className="w-6 h-6 rounded-full bg-surface-3 flex items-center justify-center text-[10px] font-bold text-muted uppercase flex-shrink-0">
                          {log.user?.name ? log.user.name.slice(0, 2) : (log.user?.email ? log.user.email.slice(0, 2) : "SY")}
                        </div>
                        <div className="flex flex-col">
                          <span className="text-sm font-medium text-ink truncate max-w-[160px]">
                            {log.user?.name || log.user?.email || "System"}
                          </span>
                        </div>
                      </div>
                    </td>
                    <td className="py-3 px-4 align-top">
                      <span className={`inline-flex items-center px-2 py-1 rounded-md text-[11px] font-semibold uppercase tracking-wide border ${getActionBadgeStyle(log.action)}`}>
                        {log.action}
                      </span>
                    </td>
                    <td className="py-3 px-4 align-top">
                      <div className="text-sm text-ink-2">
                        {log.entityType}
                      </div>
                      {log.entityId && (
                        <div className="text-xs font-mono text-muted mt-0.5">
                          {log.entityId}
                        </div>
                      )}
                    </td>
                    <td className="py-3 px-4 align-top text-right">
                      <button
                        onClick={() => setSelectedLog(log)}
                        className="inline-flex items-center justify-center p-1.5 rounded-md text-muted hover:text-ink dark:hover:text-ink hover:bg-surface-2 transition-colors"
                        aria-label="View Details"
                        title="View Details"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={5} className="py-12 text-center">
                    <div className="flex flex-col items-center justify-center">
                      <Search className="w-8 h-8 text-faint mb-3" />
                      <p className="text-muted font-medium">No audit logs found matching your criteria.</p>
                      <button 
                        onClick={() => router.push(pathname)}
                        className="mt-2 text-sm text-accent hover:underline"
                      >
                        Clear filters
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <Pagination
          totalCount={totalLogs}
          page={currentPage}
          perPage={itemsPerPage}
          itemName="logs"
          sizeParam="limit"
        />
      </div>

      <AuditLogDetailsDialog
        isOpen={!!selectedLog}
        onClose={() => setSelectedLog(null)}
        log={selectedLog}
      />
    </>
  );
}

import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { canViewAuditLogs } from "@/lib/permissions";
import { Role } from "@prisma/client";
import Link from "next/link";
import { redirect } from "next/navigation";
import AuditLogsClient from "./AuditLogsClient";

export const metadata = {
  title: "Audit Logs | xSypher",
};

export default async function AuditLogsPage(props: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  const searchParams = await props.searchParams;
  const currentUser = await getCurrentUser();
  if (!currentUser) {
    redirect("/admin/login");
  }

  if (!canViewAuditLogs(currentUser.role as Role)) {
    return (
      <div className="cs-card" style={{ maxWidth: "600px", margin: "2rem auto", textAlign: "center", padding: "2.5rem 1.5rem" }}>
        <div style={{
          width: "48px", height: "48px", borderRadius: "50%", backgroundColor: "var(--accent-soft)",
          color: "var(--accent)", display: "inline-flex", alignItems: "center", justifyContent: "center",
          margin: "0 auto 1.25rem"
        }}>
          <svg width="24" height="24" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        </div>
        <h2 style={{ fontFamily: "var(--f-display)", fontSize: "1.35rem", marginBottom: "0.5rem" }}>
          Permission Required
        </h2>
        <p style={{ color: "var(--muted)", fontSize: "0.875rem", fontFamily: "var(--f-ui)", marginBottom: "1.5rem", lineHeight: 1.6 }}>
          Only <strong>ADMIN</strong> roles can view audit logs.<br />
        </p>
        <div style={{ display: "flex", gap: "10px", justifyContent: "center", flexWrap: "wrap" }}>
          <Link href="/admin" className="btn-cs">
            Return to Dashboard
          </Link>
        </div>
      </div>
    );
  }

  const query = typeof searchParams.query === 'string' ? searchParams.query : undefined;
  const category = typeof searchParams.category === 'string' ? searchParams.category : undefined;
  const dateRange = typeof searchParams.dateRange === 'string' ? searchParams.dateRange : undefined;

  const page = typeof searchParams.page === 'string' ? parseInt(searchParams.page, 10) : 1;
  const limit = typeof searchParams.limit === 'string' ? parseInt(searchParams.limit, 10) : 25;
  const skip = (Math.max(1, page) - 1) * limit;

  // Read once, alongside the query parameters, rather than in the JSX. The
  // client renders every relative age against this single value, so the whole
  // table agrees and nothing depends on the browser's clock.
  // Server component: this runs once per request and the value is passed down,
  // so the client never reads a clock of its own.
  // eslint-disable-next-line react-hooks/purity
  const renderedAt = Date.now();

  const where: any = {};

  if (query) {
    where.OR = [
      { action: { contains: query, mode: 'insensitive' } },
      { entityType: { contains: query, mode: 'insensitive' } },
      { entityId: { contains: query, mode: 'insensitive' } },
      { user: { name: { contains: query, mode: 'insensitive' } } },
      { user: { email: { contains: query, mode: 'insensitive' } } },
    ];
  }

  if (category && category !== 'All') {
    if (category === 'Publishing') {
      where.action = { in: ['ARTICLE_PUBLISH', 'ARTICLE_UPDATE', 'ARTICLE_CREATE', 'ARTICLE_DELETE'] };
    } else if (category === 'Authentication') {
      where.action = { in: ['LOGIN_SUCCESS', 'LOGIN_FAILED', 'PASSWORD_RESET', 'LOGOUT'] };
    } else if (category === 'User Management') {
      where.action = { in: ['USER_INVITED', 'USER_REVOKED', 'ROLE_CHANGED'] };
    } else if (category === 'System') {
      where.action = { in: ['CONFIG_CHANGE', 'TAXONOMY_ADD', 'TAXONOMY_REMOVE'] };
    }
  }

  if (dateRange && dateRange !== 'All Time') {
    const now = new Date();
    const startDate = new Date();
    if (dateRange === '24h') {
      startDate.setHours(now.getHours() - 24);
    } else if (dateRange === '7d') {
      startDate.setDate(now.getDate() - 7);
    } else if (dateRange === '30d') {
      startDate.setDate(now.getDate() - 30);
    }
    where.createdAt = { gte: startDate };
  }

  const [logs, totalLogs] = await Promise.all([
    db.auditLog.findMany({
      where,
      orderBy: { createdAt: "desc" },
      skip,
      take: limit,
      include: {
        user: {
          select: { name: true, email: true },
        },
      },
    }),
    db.auditLog.count({ where })
  ]);

  return (
    <>
      <header className="mb-8">
        <h1 className="text-3xl font-display font-semibold text-ink tracking-tight">Audit Logs</h1>
        <p className="text-muted mt-2 text-[15px]">System-wide security tracking, editorial activity, and access history.</p>
      </header>

      <AuditLogsClient 
        logs={logs} 
        totalLogs={totalLogs} 
        currentPage={page} 
        itemsPerPage={limit}
        renderedAt={renderedAt}
      />
    </>
  );
}

import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { canModerateComments } from "@/lib/permissions";
import { Role, CommentStatus } from "@prisma/client";
import { db } from "@/lib/db";
import CommentsQueueClient from "./CommentsQueueClient";

export const dynamic = "force-dynamic";

export const metadata = {
  title: "Comments Moderation | xSypher",
};

export default async function CommentsPage(props: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  const searchParams = await props.searchParams;
  const user = await getCurrentUser();
  if (!user) redirect("/admin/login");

  if (!canModerateComments(user.role as Role)) {
    redirect("/admin");
  }

  const query = typeof searchParams.query === 'string' ? searchParams.query : undefined;
  const tab = typeof searchParams.tab === 'string' ? searchParams.tab : 'All';
  const page = typeof searchParams.page === 'string' ? parseInt(searchParams.page, 10) : 1;
  const limit = typeof searchParams.limit === 'string' ? parseInt(searchParams.limit, 10) : 20;
  const skip = (Math.max(1, page) - 1) * limit;

  const where: any = {};

  if (query) {
    where.OR = [
      { displayName: { contains: query, mode: 'insensitive' } },
      { body: { contains: query, mode: 'insensitive' } },
    ];
  }

  if (tab !== 'All') {
    if (tab === 'Pending') where.status = 'PENDING';
    if (tab === 'Approved') where.status = 'APPROVED';
    if (tab === 'Spam') where.status = 'SPAM';
    if (tab === 'Trash') where.status = 'REJECTED';
  }

  const [comments, totalComments, counts] = await Promise.all([
    db.comment.findMany({
      where,
      orderBy: { createdAt: "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        articleSlug: true,
        displayName: true,
        body: true,
        status: true,
        ipHash: true,
        createdAt: true,
        moderatorNote: true,
        moderator: { select: { name: true } },
      },
    }),
    db.comment.count({ where }),
    db.comment.groupBy({
      by: ['status'],
      _count: true,
    })
  ]);

  const stats = {
    total: 0,
    pending: 0,
    approved: 0,
    spam: 0,
    rejected: 0,
  };

  counts.forEach((c) => {
    stats.total += c._count;
    if (c.status === 'PENDING') stats.pending = c._count;
    if (c.status === 'APPROVED') stats.approved = c._count;
    if (c.status === 'SPAM') stats.spam = c._count;
    if (c.status === 'REJECTED') stats.rejected = c._count;
  });

  const formattedComments = comments.map(c => ({
    ...c,
    createdAt: c.createdAt.toISOString(),
  }));

  return (
    <>
      <header className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-display font-semibold text-ink tracking-tight">Comments</h1>
          <p className="text-muted mt-2 text-[15px]">Review reader discourse, moderate comments, and manage spam.</p>
        </div>
      </header>

      <CommentsQueueClient 
        initialComments={formattedComments} 
        stats={stats}
        totalItems={totalComments}
        currentPage={page}
        itemsPerPage={limit}
      />
    </>
  );
}

