import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { Role, Prisma } from "@prisma/client";
import { canViewReviewQueue } from "@/lib/permissions";
import { REVIEW_QUEUE_LIMIT } from "@/lib/queries";
import Link from "next/link";
import Image from "next/image";

export const metadata = {
  title: "Review Queue · xSypher",
};

interface SearchParams {
  category?: string;
  author?: string;
  claim?: "me" | "unclaimed" | "other";
  resubmissions?: "true";
  sort?: "oldest" | "newest" | "author";
}

function formatAge(date: Date): string {
  const diffMs = Date.now() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return "just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  return `${diffDays}d ago`;
}

export default async function ReviewQueuePage(props: {
  searchParams: Promise<SearchParams>;
}) {
  const searchParams = await props.searchParams;
  const user = await getCurrentUser();
  if (!user) redirect("/admin/login");

  const dbUser = await db.user.findUnique({
    where: { id: user.id },
    select: { role: true },
  });

  const userRole = (dbUser?.role || user.role || "AUTHOR").toUpperCase() as Role;

  if (!canViewReviewQueue(userRole)) {
    redirect("/admin");
  }

  const { category, author, claim, resubmissions, sort = "oldest" } = searchParams;

  // Build filters
  const filterConditions: Prisma.ArticleWhereInput[] = [
    { status: "SUBMITTED" }
  ];

  if (category) {
    filterConditions.push({ category: { slug: category } });
  }

  if (author) {
    filterConditions.push({ authorModel: { slug: author } });
  }

  if (claim === "me") {
    filterConditions.push({ reviewedById: user.id });
  } else if (claim === "unclaimed") {
    filterConditions.push({ reviewedById: null });
  } else if (claim === "other") {
    filterConditions.push({
      reviewedById: { not: null, notIn: [user.id] }
    });
  }

  if (resubmissions === "true") {
    // Requires revisions count > 0.
    filterConditions.push({
      revisions: { some: {} }
    });
  }

  // Build sort
  const orderBy: Prisma.ArticleOrderByWithRelationInput[] = [];
  if (sort === "newest") {
    orderBy.push({ submittedAt: "desc" });
  } else if (sort === "author") {
    orderBy.push({ authorModel: { name: "asc" } });
  } else {
    // Default to oldest
    orderBy.push({ submittedAt: "asc" });
  }

  const articles = await db.article.findMany({
    where: { AND: filterConditions },
    orderBy,
    // A review queue that has grown past this is a staffing problem, not a
    // paging problem, but the query still needs a ceiling so one backlogged
    // week cannot take the page down.
    take: REVIEW_QUEUE_LIMIT,
    // Explicit select rather than include: include is SELECT *, which pulled
    // contentJson and every SEO column for rows that render neither.
    // contentHtml is the one body field genuinely needed here -- the card
    // shows a word count derived from it.
    select: {
      id: true,
      title: true,
      img: true,
      submittedAt: true,
      updatedAt: true,
      reviewedById: true,
      author: true,
      contentHtml: true,
      category: { select: { name: true } },
      authorModel: { select: { name: true, slug: true } },
      reviewer: { select: { name: true, email: true } },
      _count: { select: { revisions: true } }
    },
  });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: "24px" }}>
        <div>
          <h1 style={{ fontSize: "24px", fontWeight: 700, margin: "0 0 4px 0" }}>Review Queue</h1>
          <p style={{ color: "var(--muted)", margin: 0, fontSize: "14px" }}>
            Articles awaiting editorial decision.
          </p>
        </div>
      </div>

      <div style={{ display: "flex", gap: "16px", marginBottom: "24px", flexWrap: "wrap", fontSize: "13px" }}>
        {/* Filters */}
        <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
          <span style={{ color: "var(--muted)" }}>Claim:</span>
          <Link href={`/admin/review?claim=me&sort=${sort}`} className={`btn-cs ${claim === "me" ? "primary" : ""}`}>My Claims</Link>
          <Link href={`/admin/review?claim=unclaimed&sort=${sort}`} className={`btn-cs ${claim === "unclaimed" ? "primary" : ""}`}>Unclaimed</Link>
          <Link href={`/admin/review?sort=${sort}`} className={`btn-cs ${!claim ? "primary" : ""}`}>All</Link>
        </div>

        <div style={{ display: "flex", gap: "8px", alignItems: "center", marginLeft: "auto" }}>
          <span style={{ color: "var(--muted)" }}>Sort:</span>
          <Link href={`/admin/review?sort=oldest&claim=${claim || ""}`} className={`btn-cs ${sort === "oldest" ? "primary" : ""}`}>Oldest</Link>
          <Link href={`/admin/review?sort=newest&claim=${claim || ""}`} className={`btn-cs ${sort === "newest" ? "primary" : ""}`}>Newest</Link>
        </div>
      </div>

      <div style={{ display: "flex", flexDirection: "column" }}>
        {articles.length === 0 ? (
          <div style={{ padding: "48px 16px", textAlign: "center", background: "var(--surface)", borderRadius: "var(--r-md)" }}>
            <p style={{ color: "var(--muted)", margin: 0 }}>Queue is empty. Great job!</p>
          </div>
        ) : (
          articles.map((article) => {
            const ageMs = Date.now() - new Date(article.submittedAt || article.updatedAt).getTime();
            const ageDays = ageMs / (1000 * 60 * 60 * 24);
            let ageColor = "var(--ink-muted)";
            if (ageDays >= 3) ageColor = "var(--error)";
            else if (ageDays >= 1) ageColor = "var(--warning)";

            const isClaimedByMe = article.reviewedById === user.id;
            const wordCount = article.contentHtml ? article.contentHtml.replace(/<[^>]*>?/gm, '').split(/\s+/).length : 0;

            return (
              <div key={article.id} style={{ 
                display: "flex", 
                padding: "16px", 
                borderBottom: "1px solid var(--line)",
                gap: "16px",
                alignItems: "center"
              }}>
                {article.img ? (
                  <div style={{ width: "80px", height: "60px", position: "relative", borderRadius: "4px", overflow: "hidden", flexShrink: 0 }}>
                    <Image src={article.img} alt={article.title} fill style={{ objectFit: "cover" }} />
                  </div>
                ) : (
                  <div style={{ width: "80px", height: "60px", background: "var(--surface-2)", borderRadius: "4px", flexShrink: 0 }} />
                )}

                <div style={{ flex: 1, minWidth: 0 }}>
                  <Link href={`/admin/review/${article.id}`} style={{ fontWeight: 600, fontSize: "15px", color: "var(--ink)", textDecoration: "none", display: "block", marginBottom: "4px" }}>
                    {article.title}
                  </Link>
                  <div style={{ fontSize: "12px", color: "var(--ink-muted)", display: "flex", gap: "12px", flexWrap: "wrap" }}>
                    <span>By <strong>{article.authorModel?.name || article.author || "Unknown"}</strong></span>
                    <span>{article.category?.name || "Uncategorized"}</span>
                    <span>~{wordCount} words</span>
                    {article._count.revisions > 0 && (
                      <span style={{ color: "var(--accent)" }}>Pass {article._count.revisions + 1}</span>
                    )}
                  </div>
                </div>

                <div style={{ textAlign: "right", fontSize: "12px", display: "flex", flexDirection: "column", gap: "6px", alignItems: "flex-end", flexShrink: 0 }}>
                  <div style={{ color: ageColor, fontWeight: ageDays >= 1 ? 600 : 400 }}>
                    {article.submittedAt ? formatAge(new Date(article.submittedAt)) : "Unknown age"}
                  </div>
                  {article.reviewedById ? (
                    <span style={{ 
                      padding: "2px 6px", 
                      borderRadius: "4px", 
                      background: isClaimedByMe ? "rgba(16, 185, 129, 0.1)" : "var(--surface-2)", 
                      color: isClaimedByMe ? "var(--success)" : "var(--ink-muted)",
                      fontWeight: 600
                    }}>
                      {isClaimedByMe ? "Claimed by you" : `Claimed by ${article.reviewer?.name || "Another"}`}
                    </span>
                  ) : (
                    <span style={{ padding: "2px 6px", borderRadius: "4px", background: "var(--surface-2)", color: "var(--muted)" }}>
                      Unclaimed
                    </span>
                  )}
                  <Link href={`/admin/review/${article.id}`} className="btn-cs" style={{ marginTop: "4px", padding: "4px 12px", height: "auto" }}>
                    {isClaimedByMe ? "Continue Review" : "Open"}
                  </Link>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { showToast } from "@/lib/utils";
import { updateNotificationPrefs } from "@/app/actions/profile";

export default function AccountForm({ user }: { user: any }) {
  const [isPending, setIsPending] = useState(false);
  const [password, setPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  // Notification Prefs
  const initialPrefs = user?.notificationPrefs || {
    emailAlerts: true,
    weeklyDigest: false,
    reviewUpdates: true
  };
  const [prefs, setPrefs] = useState(initialPrefs);

  const handlePasswordSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      showToast("Passwords do not match");
      return;
    }
    if (newPassword.length < 8) {
      showToast("Password must be at least 8 characters");
      return;
    }

    setIsPending(true);
    // Add real password change API call here later
    setTimeout(() => {
      showToast("Password updated successfully (Mock)");
      setPassword("");
      setNewPassword("");
      setConfirmPassword("");
      setIsPending(false);
    }, 1000);
  };

  const handlePrefsSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsPending(true);
    try {
      const res = await updateNotificationPrefs({
        emailAlerts: !!prefs.emailAlerts,
        weeklyDigest: !!prefs.weeklyDigest,
        reviewUpdates: !!prefs.reviewUpdates,
      });
      if (res.success) {
        showToast("Notification preferences saved.");
      } else {
        showToast(`Error: ${res.error || "Failed to save preferences"}`);
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to save preferences";
      showToast(`Error: ${msg}`);
    } finally {
      setIsPending(false);
    }
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>

      {/* ── Section: Password Management ────────────────────────── */}
      <div className="cs-settings-section">
        <div className="cs-settings-section-label">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
          Change Password
        </div>
        <div className="cs-settings-body">
          <form onSubmit={handlePasswordSubmit} className="cs-settings-grid">
            <div className="cs-settings-full">
              <label className="ed-label">Current Password</label>
              <input type="password" className="ed-input" value={password} onChange={e => setPassword(e.target.value)} required />
            </div>
            <div>
              <label className="ed-label">New Password</label>
              <input type="password" className="ed-input" value={newPassword} onChange={e => setNewPassword(e.target.value)} required minLength={8} />
            </div>
            <div>
              <label className="ed-label">Confirm New Password</label>
              <input type="password" className="ed-input" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required minLength={8} />
            </div>
            <div className="cs-settings-full" style={{ display: "flex", justifyContent: "flex-end" }}>
              <button type="submit" className="btn-cs primary" disabled={isPending}>Update Password</button>
            </div>
          </form>
        </div>
      </div>

      {/* ── Section: Notification Preferences ─────────────────── */}
      <div className="cs-settings-section">
        <div className="cs-settings-section-label">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>
          Notification Preferences
        </div>
        <div className="cs-settings-body">
          <form onSubmit={handlePrefsSubmit}>
            <div style={{ display: "flex", flexDirection: "column", gap: "12px", marginBottom: "20px" }}>
              <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontSize: "14px", color: "var(--ink)" }}>
                <input type="checkbox" checked={prefs.emailAlerts} onChange={e => setPrefs({...prefs, emailAlerts: e.target.checked})} style={{ width: "16px", height: "16px", accentColor: "var(--accent)" }} />
                Important Account & Security Alerts
              </label>
              <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontSize: "14px", color: "var(--ink)" }}>
                <input type="checkbox" checked={prefs.reviewUpdates} onChange={e => setPrefs({...prefs, reviewUpdates: e.target.checked})} style={{ width: "16px", height: "16px", accentColor: "var(--accent)" }} />
                Article Review Status Updates
              </label>
              <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontSize: "14px", color: "var(--ink)" }}>
                <input type="checkbox" checked={prefs.weeklyDigest} onChange={e => setPrefs({...prefs, weeklyDigest: e.target.checked})} style={{ width: "16px", height: "16px", accentColor: "var(--accent)" }} />
                Weekly Publication Digest
              </label>
            </div>
            <div style={{ display: "flex", justifyContent: "flex-end" }}>
              <button type="submit" className="btn-cs" disabled={isPending}>Save Preferences</button>
            </div>
          </form>
        </div>
      </div>

    </div>
  );
}

