"use client";

import { useEffect } from "react";
import { Check, Copy } from "lucide-react";
import { createRoot } from "react-dom/client";

// A small functional component for the button itself
function CopyButton({ textToCopy }: { textToCopy: string }) {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(textToCopy);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (e) {
      // Fallback for older browsers
      const textarea = document.createElement("textarea");
      textarea.value = textToCopy;
      textarea.style.position = "fixed";
      textarea.style.opacity = "0";
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <button
      onClick={handleCopy}
      type="button"
      className="absolute top-2.5 right-2.5 px-2 py-1.5 rounded-md bg-[var(--surface)] border border-[var(--line-2)] text-[var(--ink)] hover:bg-[var(--surface-2)] hover:border-[var(--accent)] transition-all z-20 shadow-sm flex items-center justify-center opacity-100 lg:opacity-0 lg:group-hover:opacity-100 cursor-pointer"
      aria-label="Copy code"
      title="Copy code"
    >
      {copied ? (
        <Check className="w-3.5 h-3.5 text-emerald-500"/>
      ) : (
        <Copy className="w-3.5 h-3.5 text-[var(--ink)]"/>
      )}
    </button>
  );
}

// Ensure React is in scope for the client root rendering
import React from "react";

export default function CodeBlockEnhancer() {
  useEffect(() => {
    const container = document.querySelector(".tiptap-content") || document.querySelector(".prose");
    if (!container) return;

    const preElements = container.querySelectorAll("pre");

    preElements.forEach((pre) => {
      // Skip if already enhanced
      if (pre.dataset.enhanced) return;
      pre.dataset.enhanced = "true";

      // Wrap in a group for hover opacity control
      pre.classList.add("group", "relative");

      // Extract raw code for copying (without HTML tags)
      const codeEl = pre.querySelector("code");
      const textToCopy = codeEl ? codeEl.textContent || "" : pre.textContent || "";

      // Create a mount point for the React component
      const mountPoint = document.createElement("div");
      pre.appendChild(mountPoint);

      // Render the button
      const root = createRoot(mountPoint);
      root.render(<CopyButton textToCopy={textToCopy} />);
    });
  }, []);

  return null; // Component does not render anything directly in the flow
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { getComments, postComment, type PublicComment } from "@/app/actions/comments";

interface CommentsSectionProps {
  articleSlug: string;
}

export default function CommentsSection({ articleSlug }: CommentsSectionProps) {
  const [comments, setComments] = useState<PublicComment[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [text, setText] = useState("");
  const [submitResult, setSubmitResult] = useState<{ success?: boolean; error?: string } | null>(null);
  const [isPending, startTransition] = useTransition();

  useEffect(() => {
    getComments(articleSlug).then((data) => {
      setComments(data);
      setIsLoading(false);
    });
  }, [articleSlug]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitResult(null);

    const formData = new FormData();
    formData.append("name", name);
    formData.append("email", email);
    formData.append("comment", text);

    startTransition(async () => {
      const res = await postComment(articleSlug, formData);
      setSubmitResult(res);
      if (res.success) {
        setName("");
        setEmail("");
        setText("");
      }
    });
  };

  const formatDate = (iso: string) => {
    try {
      return new Date(iso).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
      });
    } catch {
      return iso;
    }
  };

  return (
    <section id="comments" className="comments scroll-mt-28" aria-labelledby="cmtH">
      <h2 id="cmtH">Discussion ({isLoading ? "…" : comments.length})</h2>

      <div id="cmtList" role="list" aria-live="polite" aria-busy={isLoading}>
        {isLoading ? (
          <p style={{ color: "var(--ink-muted)", fontSize: "14px" }}>Loading discussion…</p>
        ) : comments.length === 0 ? (
          <p style={{ color: "var(--ink-muted)", fontSize: "14px" }}>
            No comments yet — be the first to join the discussion.
          </p>
        ) : (
          comments.map((c) => (
            <div key={c.id} className="cmt" role="listitem">
              {/* Gravatar via email hash */}
              <img
                src={`https://www.gravatar.com/avatar/${c.emailHash}?d=mp&s=48`}
                alt=""
                className="ava lg"
                style={{ fontSize: "16px", borderRadius: "50%" }}
                aria-hidden="true"
              />
              <div className="cmt-body">
                <div className="cmt-head">
                  <b>{c.displayName}</b>
                  <time dateTime={c.createdAt}>{formatDate(c.createdAt)}</time>
                </div>
                <p>{c.body}</p>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Pending state notification */}
      {submitResult?.success && (
        <div
          role="status"
          aria-live="polite"
          style={{
            padding: "12px 16px",
            marginBottom: "20px",
            background: "var(--surface-2)",
            borderRadius: "var(--r-md)",
            border: "1px solid var(--line)",
            fontSize: "14px",
            color: "var(--ink)",
          }}
        >
          <strong>Your comment is awaiting moderation.</strong> It will appear here once approved.
        </div>
      )}

      <form className="cmt-form" id="cmtForm" onSubmit={handleSubmit} noValidate>
        <div className="cf-row">
          <div>
            <label className="sr-only" htmlFor="cmtName">Name <span aria-hidden="true">*</span></label>
            <input
              className="f-input"
              id="cmtName"
              required
              maxLength={60}
              placeholder="Your name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              disabled={isPending}
              autoComplete="name"
            />
          </div>
          <div>
            <label className="sr-only" htmlFor="cmtEmail">
              Email <span style={{ textTransform: "none", letterSpacing: 0 }}>(not published)</span>
              <span aria-hidden="true"> *</span>
            </label>
            <input
              className="f-input"
              id="cmtEmail"
              type="email"
              required
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              disabled={isPending}
              autoComplete="email"
            />
          </div>
        </div>
        <div>
          <label className="sr-only" htmlFor="cmtText">Comment <span aria-hidden="true">*</span></label>
          <textarea
            className="f-input"
            id="cmtText"
            required
            minLength={10}
            maxLength={1200}
            placeholder="Join the discussion — be specific, be kind."
            value={text}
            onChange={(e) => setText(e.target.value)}
            disabled={isPending}
          />
          <span style={{ fontSize: "11px", color: "var(--ink-muted)" }}>{text.length}/1200</span>
        </div>

        {submitResult?.error && (
          <div
            role="alert"
            aria-live="assertive"
            style={{
              color: "var(--error, #e53e3e)",
              fontSize: "13px",
              padding: "8px 12px",
              background: "rgba(229,62,62,0.08)",
              borderRadius: "var(--r-sm)",
            }}
          >
            {submitResult.error}
          </div>
        )}

        <div style={{ display: "flex", alignItems: "center", gap: "14px", flexWrap: "wrap" }}>
          <button className="btn btn-solid" type="submit" disabled={isPending}>
            {isPending ? "Posting…" : "Post Comment"}
          </button>
          <span style={{ fontSize: "12px", color: "var(--ink-muted)" }}>
            All comments are moderated before publication.
          </span>
        </div>
      </form>
    </section>
  );
}

import Image from "next/image";
import Link from "next/link";
import { Article, Category } from "@prisma/client";
import { getImgSrc, timeAgo } from "@/lib/utils";
import RelativeTime from "@/components/common/RelativeTime";

export type StoryCardArticle = Partial<Article> & {
  id: string;
  slug: string;
  title: string;
  deck?: string | null;
  author?: string | null;
  img?: string | null;
  createdAt?: Date | string | number;
  category?: Partial<Category> | null;
  cat?: string;
  age?: number;
  mins?: number;
  [key: string]: any;
};

interface Props {
  article: StoryCardArticle;
  showDeck?: boolean;
}

export default function StoryCard({ article: a, showDeck = true }: Props) {
  // Surface the main category (parent) for SEO and header alignment if it's a subcategory
  const mainCat = (a.category as any)?.parent;
  const subCat = mainCat ? a.category : null;
  const catName = mainCat 
    ? `${mainCat.name} / ${subCat?.name}`
    : (a.category?.name || (typeof a.cat === "string" ? a.cat.toUpperCase() : "News"));
  const catSlug = (mainCat || a.category)?.slug || (typeof a.cat === "string" ? a.cat.toLowerCase() : "news");

  // Relative time is computed in the browser, not here.
  //
  // This is a server component and these listings are cached with ISR, so a
  // Date.now() here was frozen into the cached HTML -- a story kept claiming
  // "2 minutes ago" for the whole revalidate window. Passing the absolute
  // timestamp down lets the client render it against the real current time.
  //
  // The legacy `age` field (minutes, from mock data) has no absolute timestamp
  // to hand over, so it still formats inline. That path is not served from the
  // database and is not cached against a clock.
  const ageNode = a.createdAt
    ? <RelativeTime dateTime={new Date(a.createdAt).toISOString()} />
    : typeof a.age === "number"
      ? timeAgo(a.age)
      : null;

  return (
    <article className="story-card" data-reveal suppressHydrationWarning>
      <Link href={`/article/${a.slug}`} className="ph r-32" tabIndex={-1} aria-hidden="true">
        <Image 
          src={getImgSrc(a.img || "", 640, 427)} 
          alt={a.title} 
          fill
          className="object-cover"
        />
      </Link>
      <div>
        <Link href={`/category/${catSlug}`} className="kicker plain">
          {catName}
        </Link>
        <h3>
          <Link href={`/article/${a.slug}`}>
            <span className="hlink">{a.title}</span>
          </Link>
        </h3>
        {showDeck && <p className="story-deck">{a.deck}</p>}
        <div className="byline" style={{ marginTop: "8px" }}>
          <span><span className="text-[var(--accent)] hover:underline">{a.author || "xSypher Staff"}</span> · {ageNode} · {a.readingTime || a.mins || 1} min read</span>
        </div>
      </div>
    </article>
  );
}

