                )}

                {/* Remaining articles grid */}
                {articles.length > 1 && (
                  <div className="ap-articles-rest">
                    {articles.slice(1).map(article => (
                      <StoryCard key={article.id} article={article} showDeck={false} />
                    ))}
                  </div>
                )}
              </div>
            ) : (
              <div className="ap-empty">
                <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round">
                  <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
                  <polyline points="14 2 14 8 20 8"/>
                  <line x1="16" y1="13" x2="8" y2="13"/>
                  <line x1="16" y1="17" x2="8" y2="17"/>
                </svg>
                <p>No published articles yet.</p>
              </div>
            )}
          </section>
        </div>

        {/* Right Sidebar */}
        <Sidebar />

      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import Link from "next/link";
import { useRouter, usePathname, useSearchParams } from "next/navigation";

interface SubcategoryStripProps {
  subcategories: { name: string; slug: string }[];
  parentSlug: string;
}

export default function SubcategoryStrip({ subcategories, parentSlug }: SubcategoryStripProps) {
  const searchParams = useSearchParams();
  const currentSub = searchParams.get("sub");
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!scrollRef.current) return;

    const timeoutId = setTimeout(() => {
      const activeElement = scrollRef.current?.querySelector(".active-sub");
      if (activeElement) {
        activeElement.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
      }
    }, 50);

    return () => clearTimeout(timeoutId);
  }, [currentSub]);

  if (!subcategories || subcategories.length === 0) return null;

  return (
    <div className="w-full border-b border-[var(--line)] bg-[var(--bg)]/90 backdrop-blur-md sticky top-14 z-30 mb-8 overflow-hidden">
      <div 
        ref={scrollRef}
        className="wrap flex items-center gap-2 overflow-x-auto py-3 px-4 sm:px-6 lg:px-8 no-scrollbar"
        style={{ scrollBehavior: "smooth", msOverflowStyle: 'none', scrollbarWidth: 'none' }}
      >
        <Link
          href={`/category/${parentSlug}`}
          className={`shrink-0 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-colors ${
            !currentSub 
              ? "bg-[var(--ink)] text-[var(--surface)] active-sub" 
              : "bg-[var(--surface-2)] text-[var(--muted)] hover:text-[var(--ink)] hover:bg-[var(--surface-3)]"
          }`}
        >
          All
        </Link>
        {subcategories.map((sub) => {
          const isActive = currentSub === sub.slug;
          return (
            <Link
              key={sub.slug}
              href={`/category/${parentSlug}?sub=${sub.slug}`}
              className={`shrink-0 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-colors ${
                isActive 
                  ? "bg-[var(--ink)] text-[var(--surface)] active-sub" 
                  : "bg-[var(--surface-2)] text-[var(--muted)] hover:text-[var(--ink)] hover:bg-[var(--surface-3)]"
              }`}
            >
              {sub.name}
            </Link>
          );
        })}
      </div>
    </div>
  );
}

"use client";

// Client-side because bulk selection needs state. Nothing server-only is
// imported here -- no db, no auth; authorize() is a pure function over a static
// capability map, and the map is not a secret: it describes which role may do
// what, and every one of those checks is re-run on the server before anything
// is written. Hiding a control the server would refuse anyway buys nothing.

import { useState, useMemo, useOptimistic } from "react";
import Link from "next/link";
import Image from "next/image";
import { ArticleStatus, Role } from "@prisma/client";
import { authorize } from "@/lib/capabilities";
import StatusChip from "./StatusChip";
import { fmtViews } from "@/lib/utils";
import ArticleActionMenu from "../editorial/ArticleActionMenu";
import { Eye, ExternalLink, Edit3, FileText, Plus, Clock } from "lucide-react";
import BulkActionBar from "./BulkActionBar";

interface ArticleRow {
  id: string;
  slug: string;
  title: string;
  deck: string | null;
  img: string | null;
  status: ArticleStatus;
  featured: boolean;
  views: number;
  authorId?: string | null;
  author: string | null;
  createdAt: Date | string;
  updatedAt: Date | string;
  publishedAt: Date | string | null;
  scheduledFor: Date | string | null;
  authorModel: {
    id: string;
    name: string;
    slug: string;
    avatar: string | null;
  } | null;
  category: {
    id: string;
    name: string;
    slug: string;
  } | null;
  tags: { id: string; name: string }[];
  _count?: {
    revisions: number;
    comments: number;
  };
}

interface ArticleIndexProps {
  articles: ArticleRow[];
  actor: { id: string; role: Role; authorId: string | null };
  emptyMessage?: string;
  emptyAction?: {
    label: string;
    href: string;
  };
  isFiltered?: boolean;
}

function relativeTime(date: Date | string): string {
  const d = new Date(date);
  const now = new Date();
  const diffMs = now.getTime() - d.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return "just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

/** Absolute date for scheduled/published times, where "in 3 days" is not enough. */
function absoluteDateTime(date: Date | string): string {
  return new Date(date).toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

export default function ArticleIndex({
  articles,
  actor,
  emptyMessage = "No articles found.",
  emptyAction,
  isFiltered,
}: ArticleIndexProps) {
  const [selected, setSelected] = useState<Set<string>>(new Set());

  // Optimistic status.
  //
  // A bulk action is a server round-trip plus a router.refresh(), which on a
  // slow connection leaves the table showing DRAFT for a second or more after
  // the editor asked to publish. The rows below read from this instead of the
  // prop so the new status paints immediately.
  //
  // The reducer takes a *map* of id -> status rather than a single status,
  // because these actions report partial success: the server validates each
  // article separately and can legitimately publish 37 of 40. Applying one
  // status to the whole selection would show three rows as published that were
  // actually rejected.
  //
  // Reverting is automatic. useOptimistic discards its overlay when the
  // transition that set it completes, at which point `articles` has been
  // refetched by router.refresh(). If the action throws, nothing was written
  // and the overlay is dropped against unchanged server data -- so the failure
  // path needs no explicit rollback, only that the mutation stay inside the
  // transition.
  // Two overlays rather than one: a status change restyles a row, a delete
  // takes it out of the list. Folding both into one reducer would mean encoding
  // "removed" as a pseudo-status, which the row renderer would then have to
  // know about.
  const [removedIds, applyOptimisticRemove] = useOptimistic(
    [] as string[],
    (_current: string[], ids: string[]) => ids
  );

  const [optimisticArticles, applyOptimisticStatus] = useOptimistic(
    articles,
    (current: ArticleRow[], patch: Record<string, ArticleStatus>) =>
      current.map((a) => (patch[a.id] ? { ...a, status: patch[a.id] } : a))
  );

  // What the table actually renders: the status overlay applied, minus anything
  // a delete is currently removing.
  const visibleArticles = useMemo(
    () =>
      removedIds.length === 0
        ? optimisticArticles
        : optimisticArticles.filter((a) => !removedIds.includes(a.id)),
    [optimisticArticles, removedIds]
  );

  // Which bulk verbs to offer at all. These mirror the capabilities the server
  // actions enforce; per-article eligibility is still decided there, so an
  // article in the wrong state is skipped and reported rather than hidden.
  const bulkCaps = useMemo(
    () => ({
      canArchive: authorize(actor.role, "article.archive"),
      canPublish: authorize(actor.role, "article.publish"),
      canSubmit: authorize(actor.role, "article.submit"),
      // Either capability puts the button on screen; the server decides per
      // article which rows it actually applies to.
      canDelete:
        authorize(actor.role, "article.delete") ||
        authorize(actor.role, "article.delete.own.draft"),
    }),
    [actor.role]
  );
  const anyBulk =
    bulkCaps.canArchive || bulkCaps.canPublish || bulkCaps.canSubmit || bulkCaps.canDelete;

  const toggle = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  // Select-all covers the current page only. It deliberately does not reach
  // across pagination: "select all 4,000 matching" is a different and much more
  // dangerous operation, and conflating the two is how people archive an
  // archive they never saw.
  const allOnPageSelected =
    visibleArticles.length > 0 && visibleArticles.every((a) => selected.has(a.id));

  const toggleAll = () => {
    setSelected((prev) =>
      allOnPageSelected ? new Set() : new Set([...prev, ...visibleArticles.map((a) => a.id)])
    );
  };

  if (visibleArticles.length === 0) {
    return (
      <div className="bg-surface border border-line rounded-xl p-12 text-center mt-4">
        <FileText className="w-10 h-10 text-faint mx-auto mb-3" />
        <p className="text-sm text-muted font-medium mb-4">
          {isFiltered
            ? "No articles match these filters."
            : emptyMessage || "No articles yet."}
        </p>
        {!isFiltered && emptyAction && (
          <Link 
            href={emptyAction.href} 
            className="inline-flex items-center gap-1.5 px-4 py-2 bg-accent hover:bg-accent-deep text-white text-xs sm:text-sm font-semibold rounded-lg shadow-xs transition-colors"
          >
            <Plus className="w-4 h-4" />
            <span>{emptyAction.label}</span>
          </Link>
        )}
      </div>
    );
  }

  return (
    <>
    {anyBulk && (
      // Mobile has no table header to hang select-all off, so it gets its own
      // row above the list rather than losing the affordance entirely.
      <div className="md:hidden flex items-center gap-2 mt-4 px-1">
        <input
          id="select-all-mobile"
          type="checkbox"
          checked={allOnPageSelected}
          onChange={toggleAll}
          className="w-4 h-4 accent-[var(--accent)] cursor-pointer"
        />
        <label htmlFor="select-all-mobile" className="text-xs font-semibold text-muted">
          Select all on this page
        </label>
      </div>
    )}
    <div className="bg-surface border border-line rounded-xl shadow-xs mt-4 overflow-hidden">
      {/* Table from md up. Below that the same data renders as stacked rows:
          a five-column table on a 375px screen forces horizontal scrolling,
          which hides the actions column exactly where it is hardest to find. */}
      <table className="w-full border-collapse text-left text-sm admin-table" aria-label="Articles">
        <caption className="sr-only">Article list</caption>
        <thead>
          <tr className="border-b border-line bg-surface-2/60">
            {anyBulk && (
              <th className="py-3 pl-4 pr-0 w-10">
                <input
                  type="checkbox"
                  checked={allOnPageSelected}
                  onChange={toggleAll}
                  className="w-4 h-4 accent-[var(--accent)] cursor-pointer align-middle"
                  aria-label={
                    allOnPageSelected
                      ? "Deselect all articles on this page"
                      : "Select all articles on this page"
                  }
                />
              </th>
            )}
            <th className="py-3 px-4 font-semibold text-[11px] tracking-wider uppercase text-muted w-24">
              <span className="sr-only">Thumbnail</span>
            </th>
            <th className="py-3 px-4 font-semibold text-[11px] tracking-wider uppercase text-muted">
              Article
            </th>
            <th className="py-3 px-4 font-semibold text-[11px] tracking-wider uppercase text-muted w-36 hidden md:table-cell">
              Status
            </th>
            <th className="py-3 px-4 font-semibold text-[11px] tracking-wider uppercase text-muted w-28 text-right hidden lg:table-cell">
              Views
            </th>
            <th className="py-3 px-4 font-semibold text-[11px] tracking-wider uppercase text-muted w-28 text-right">
              Actions
            </th>
          </tr>
        </thead>
        <tbody className="divide-y divide-line">
          {visibleArticles.map((a) => {
            const authorName = a.authorModel?.name || a.author || "Unknown";
            const categoryName = (a.category as any)?.parent?.name || a.category?.name || "";

            return (
              <tr
                key={a.id}
                className={`transition-colors ${
                  selected.has(a.id) ? "bg-surface-3" : "hover:bg-surface-2/70"
                }`}
              >
                {anyBulk && (
                  <td className="py-3.5 pl-4 pr-0 align-middle w-10" data-label="Select">
                    <input
                      type="checkbox"
                      checked={selected.has(a.id)}
                      onChange={() => toggle(a.id)}
                      className="w-4 h-4 accent-[var(--accent)] cursor-pointer align-middle"
                      aria-label={`Select "${a.title || "Untitled article"}"`}
                    />
                  </td>
                )}
                {/* Thumbnail */}
                <td className="p-3.5 align-middle w-24" data-label="Thumbnail">
                  {a.img ? (
                    <div className="w-20 h-12 rounded-lg overflow-hidden border border-line bg-surface-2 shrink-0 relative">
                      <Image
                        src={a.img}
                        alt=""
                        fill
                        className="object-cover"
                        sizes="80px"
                      />
                    </div>
                  ) : (
                    <div className="w-20 h-12 rounded-lg border border-line bg-surface-2 flex items-center justify-center font-bold text-base text-muted shrink-0">
                      {(a.title || "?").charAt(0).toUpperCase()}
                    </div>
                  )}
                </td>

                {/* Primary — title + metadata */}
                <td className="p-3.5 align-middle" data-label="Article">
                  <div className="min-w-0 max-w-xl">
                    {/* The headline opens the read-only detail hub, not the
                        editor. Clicking a title to inspect something should not
                        drop the actor into an editing surface -- and a reviewer
                        holding article.view.all without any edit right could not
                        follow the old link at all. The pencil below still goes
                        straight to the editor. */}
                    <Link
                      href={`/admin/articles/${a.id}`}
                      className="text-sm font-semibold text-ink hover:text-accent transition-colors line-clamp-2 block leading-snug"
                    >
                      {a.title || "Untitled article"}
                    </Link>
                    <div className="flex flex-wrap items-center gap-2 mt-1.5 text-xs text-muted">
                      <span className="font-medium text-ink-2">{authorName}</span>
                      {categoryName && (
                        <>
                          <span className="text-faint">·</span>
                          <span className="inline-flex items-center px-2 py-0.5 rounded bg-surface-2 border border-line text-[11px] font-medium text-ink-2">
                            {categoryName}
                          </span>
                        </>
                      )}
                      <span className="text-faint">·</span>
                      <span className="text-[11px]">{relativeTime(a.updatedAt)}</span>

                      {/* A scheduled article's whole point is the date it goes
                          live, and "in 3 days" is not precise enough to trust a
                          publication slot to. Shown absolute, and only for the
                          one status where it matters. */}
                      {a.status === "SCHEDULED" && a.scheduledFor && (
                        <>
                          <span className="text-faint">·</span>
                          <span className="inline-flex items-center gap-1 text-[11px] font-medium text-warn">
                            <Clock className="w-3 h-3" aria-hidden="true" />
                            <span>Goes live {absoluteDateTime(a.scheduledFor)}</span>
                          </span>
                        </>
                      )}

                    </div>
                  </div>
                </td>

                {/* Status — dedicated column on tablet and desktop */}
                <td className="p-3.5 align-middle md:table-cell w-36" data-label="Status">
                  <StatusChip status={a.status} />
                </td>

                {/* Views metric */}
                <td className="p-3.5 align-middle text-right lg:table-cell w-28" data-label="Views">
                  {a.status === "PUBLISHED" ? (
                    <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded bg-surface-2 border border-line text-xs font-semibold text-ink tabular-nums">
                      <Eye className="w-3.5 h-3.5 text-muted" />
                      <span>{fmtViews(a.views || 0)}</span>
                    </span>
                  ) : (
                    <span className="text-muted text-xs">—</span>
                  )}
                </td>

                {/* Actions */}
                <td className="p-3.5 align-middle text-right w-28" data-label="Actions">
                  <div className="flex items-center justify-end gap-1.5">
                    {a.status === "PUBLISHED" && (
                      <Link
                        className="p-1.5 rounded-lg text-muted hover:text-ink hover:bg-surface-3 border border-transparent hover:border-line transition-colors"
                        href={`/article/${a.slug}`}
                        target="_blank"
                        title="View on site"
                        aria-label={`View "${a.title}" on site`}
                      >
                        <ExternalLink className="w-4 h-4" />
                      </Link>
                    )}
                    <Link
                      href={`/admin/editor/${a.id}`}
                      className="p-1.5 rounded-lg text-muted hover:text-ink hover:bg-surface-3 border border-transparent hover:border-line transition-colors"
                      title={a.status === "PUBLISHED" ? "Edit article" : "Open editor"}
                      aria-label={`Edit "${a.title}"`}
                    >
                      <Edit3 className="w-4 h-4" />
                    </Link>
                    <ArticleActionMenu 
                      id={a.id} 
                      title={a.title} 
                      status={a.status}
                      canArchive={authorize(actor.role, "article.archive")}
                      canDeletePermanently={authorize(actor.role, "article.delete")}
                      canDeleteOwnDraft={authorize(actor.role, "article.delete.own.draft") && a.authorId === actor.authorId}
                    />
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>


    </div>

    <BulkActionBar
      selectedIds={[...selected]}
      onClear={() => setSelected(new Set())}
      canArchive={bulkCaps.canArchive}
      canPublish={bulkCaps.canPublish}
      canSubmit={bulkCaps.canSubmit}
      // Called from inside the bar's transition, which is what lets React tie
      // the overlay's lifetime to the action and drop it automatically when the
      // refreshed rows arrive.
      onOptimisticStatus={applyOptimisticStatus}
      onOptimisticRemove={applyOptimisticRemove}
      canDelete={bulkCaps.canDelete}
    />
    </>
  );
}

"use client";

import { useState, useTransition, startTransition } from "react";
import { archiveArticle, deleteArticlePermanently, deleteOwnDraft } from "@/app/actions/workflow";
import { showToast } from "@/lib/utils";
import { useRouter } from "next/navigation";
import ConfirmDialog from "../ui/ConfirmDialog";

interface Props {
  id: string;
  title: string;
  status: string;
  canArchive: boolean;
  canDeletePermanently: boolean;
  canDeleteOwnDraft: boolean;
}

export default function ArticleActionMenu({ id, title, status, canArchive, canDeletePermanently, canDeleteOwnDraft }: Props) {
  const [isProcessing, setIsProcessing] = useState(false);
  const [showConfirm, setShowConfirm] = useState<"archive" | "delete" | "draftDelete" | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const router = useRouter();

  // Keeps the row disabled until the refreshed server tree commits, rather than
  // re-enabling as soon as the action resolves and briefly offering actions
  // against a status that has already changed.
  const [isRefreshing, startRefresh] = useTransition();
  const busy = isProcessing || isRefreshing;

  const handleAction = (action: "archive" | "delete" | "draftDelete") => {
    setShowConfirm(null);
    setMenuOpen(false);
    setIsProcessing(true);

    const actionLabel = action === "archive"
      ? "Archiving article"
      : action === "delete"
        ? "Deleting article"
        : "Deleting draft";
    showToast(`${actionLabel}…`, "info", "premium");

    startTransition(async () => {
      try {
        let result;
        if (action === "archive") result = await archiveArticle(id);
        else if (action === "delete") result = await deleteArticlePermanently(id);
        else if (action === "draftDelete") result = await deleteOwnDraft(id);

        if (result?.ok) {
          const successLabel = action === "archive"
            ? "Article archived successfully."
            : action === "delete"
              ? "Article permanently deleted."
              : "Draft deleted successfully.";
          showToast(successLabel, "success", "premium");
          startRefresh(() => router.refresh());
        } else {
          showToast(result?.message || "The action could not be completed.", "error", "premium");
        }
      } catch (err: any) {
        showToast(err?.message || "The action could not be completed.", "error", "premium");
        console.error(err);
      } finally {
        setIsProcessing(false);
      }
    });
  };

  const showArchive = canArchive && status !== "ARCHIVED";
  const showDeletePerm = canDeletePermanently && status === "ARCHIVED";
  const showDeleteDraft = canDeleteOwnDraft && status === "DRAFT";

  if (!showArchive && !showDeletePerm && !showDeleteDraft) return null;

  return (
    <div style={{ position: "relative" }}>
      <button
        type="button"
        onClick={() => setMenuOpen(!menuOpen)}
        disabled={busy}
        className="act"
        title="More actions"
      >
        {busy ? "..." : (
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="12" cy="12" r="1" />
            <circle cx="12" cy="5" r="1" />
            <circle cx="12" cy="19" r="1" />
          </svg>
        )}
      </button>

      {menuOpen && (
        <>
          <div 
            style={{ position: "fixed", inset: 0, zIndex: 90 }} 
            onClick={() => setMenuOpen(false)}
          />
          <div style={{
            position: "absolute",
            right: 0,
            top: "100%",
            marginTop: "4px",
            background: "var(--surface)",
            border: "1px solid var(--line)",
            borderRadius: "var(--r-md)",
            boxShadow: "0 4px 6px rgba(0,0,0,0.1)",
            zIndex: 100,
            minWidth: "150px",
            padding: "4px",
            display: "flex",
            flexDirection: "column",
            gap: "2px"
          }}>
            {showArchive && (
              <button 
                onClick={() => setShowConfirm("archive")}
                style={{ textAlign: "left", padding: "8px 12px", background: "none", border: "none", fontSize: "13px", cursor: "pointer", borderRadius: "4px" }}
                className="hover-bg-surface-2"
              >
                Archive
              </button>
            )}
            {showDeleteDraft && (
              <button 
                onClick={() => setShowConfirm("draftDelete")}
                style={{ textAlign: "left", padding: "8px 12px", background: "none", border: "none", fontSize: "13px", cursor: "pointer", color: "var(--error)", borderRadius: "4px" }}
                className="hover-bg-surface-2"
              >
                Delete Draft
              </button>
            )}
            {showDeletePerm && (
              <button 
                onClick={() => setShowConfirm("delete")}
                style={{ textAlign: "left", padding: "8px 12px", background: "none", border: "none", fontSize: "13px", cursor: "pointer", color: "var(--error)", borderRadius: "4px" }}
                className="hover-bg-surface-2"
              >
                Delete Permanently
              </button>
            )}
          </div>
        </>
      )}

      <ConfirmDialog 
        isOpen={showConfirm === "archive"}
        title="Archive Article"
        description={`Are you sure you want to archive "${title}"? It will no longer be visible to the public.`}
        confirmText="Archive"
        isDestructive={true}
        onConfirm={() => handleAction("archive")}
        onCancel={() => setShowConfirm(null)}
      />

      <ConfirmDialog 
        isOpen={showConfirm === "delete"}
        title="Delete Permanently"
        description={`Are you sure you want to permanently delete "${title}"? This action cannot be undone.`}
        confirmText="Delete"
        isDestructive={true}
        requireTypedConfirmation="DELETE"
        onConfirm={() => handleAction("delete")}
        onCancel={() => setShowConfirm(null)}
      />



      <ConfirmDialog 
        isOpen={showConfirm === "draftDelete"}
        title="Delete Draft"
        description={`Are you sure you want to delete your draft "${title}"?`}
        confirmText="Delete Draft"
        isDestructive={true}
        onConfirm={() => handleAction("draftDelete")}
        onCancel={() => setShowConfirm(null)}
      />
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, useTransition, startTransition } from "react";
