          <MarkButton
            icon={Code}
            label="Inline code"
            active={editor.isActive("code")}
            onClick={() => editor.chain().focus().toggleCode().run()}
          />
          <MarkButton
            icon={Highlighter}
            label="Highlight"
            active={editor.isActive("highlight")}
            onClick={() => editor.chain().focus().toggleHighlight().run()}
          />

          <span className="eb-sep" aria-hidden="true" />

          <MarkButton
            icon={Link2}
            label={editor.isActive("link") ? "Edit link" : "Add link"}
            active={editor.isActive("link")}
            onClick={openLinkEditor}
          />
          {editor.isActive("link") && (
            <MarkButton
              icon={Link2Off}
              label="Remove link"
              onClick={() => editor.chain().focus().extendMarkRange("link").unsetLink().run()}
            />
          )}
        </div>
      )}
    </BubbleMenu>
  );
}

import React, { useCallback, useState } from 'react';
import { Editor } from '@tiptap/react';
import {
  Undo, Redo, Heading1, Heading2, Heading3, Type, Bold, Italic, Underline,
  Strikethrough, Code, List, ListOrdered, Quote, ImagePlus, Link2,
  FileCode, Minus, Maximize2, RemoveFormatting, MonitorPlay, Table as TableIcon,
  AlignLeft, AlignCenter, AlignRight, Subscript as SubscriptIcon, Superscript as SuperscriptIcon,
  Lightbulb
} from 'lucide-react';
import { InsertMediaDialog, type MediaKind } from './InsertMediaDialog';

interface EditorToolbarProps {
  editor: Editor;
  isFullscreen?: boolean;
  toggleFullscreen?: () => void;
}

// Declared at module scope on purpose.
//
// These used to live inside EditorToolbar's render body, which gave them a new
// component identity on every render. Because the toolbar re-renders on each
// editor transaction -- that is, on every keystroke -- React was unmounting and
// remounting all thirty-odd buttons continuously, discarding their DOM nodes
// and any focus on them. Hoisting makes the identity stable so React can
// reconcile the buttons instead of rebuilding them.

interface ToolbarButtonProps {
  isActive?: boolean;
  onClick: () => void;
  disabled?: boolean;
  icon: React.ElementType;
  title: string;
}

function ToolbarButton({ isActive = false, onClick, disabled = false, icon: Icon, title }: ToolbarButtonProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      title={title}
      // Tooltips are not exposed reliably to assistive tech, so the accessible
      // name is carried explicitly rather than inferred from title.
      aria-label={title}
      aria-pressed={isActive}
      className={`w-11 h-11 md:w-8 md:h-8 shrink-0 flex items-center justify-center rounded-lg transition-colors ${
        isActive
          ? 'bg-[var(--accent)]/10 text-[var(--accent)] font-semibold shadow-sm'
          : 'text-[var(--muted)] hover:text-[var(--ink)] hover:bg-[var(--surface-2)]'
      } ${disabled ? 'opacity-50 cursor-not-allowed hover:bg-transparent hover:text-[var(--muted)]' : ''}`}
    >
      <Icon className="w-4 h-4" aria-hidden="true" />
    </button>
  );
}

function Divider() {
  return <div className="h-4 w-[1px] bg-[var(--line)] mx-1" aria-hidden="true" />;
}

export function EditorToolbar({ editor, isFullscreen, toggleFullscreen }: EditorToolbarProps) {
  const setLink = useCallback(() => {
    const previousUrl = editor.getAttributes("link").href;
    const url = window.prompt("URL", previousUrl);
    if (url === null) {
      return;
    }
    if (url === "") {
      editor.chain().focus().extendMarkRange("link").unsetLink().run();
      return;
    }
    try {
      const parsed = new URL(url);
      if (!['http:', 'https:', 'mailto:'].includes(parsed.protocol)) {
        alert('Only http, https, and mailto links are allowed.');
        return;
      }
    } catch {
      alert('Please enter a valid URL.');
      return;
    }
    editor.chain().focus().extendMarkRange("link").setLink({ href: url }).run();
  }, [editor]);

  // Media insertion moved out of window.prompt and into a real dialog: the
  // prompt chain could not be cancelled partway, validated nothing, showed no
  // preview, and was unusable on touch.
  const [mediaKind, setMediaKind] = useState<MediaKind | null>(null);
  // Bumped each time the dialog opens so it remounts with empty fields. This is
  // what lets InsertMediaDialog drop its reset-on-open effect: React discards
  // the previous instance's state instead of the component clearing it by hand
  // and forcing an extra render.
  const [mediaSession, setMediaSession] = useState(0);

  const openMedia = (kind: MediaKind) => {
    setMediaSession((n) => n + 1);
    setMediaKind(kind);
  };

  const insertImage = useCallback(
    (v: { src: string; alt: string; caption: string; credit: string }) => {
      (editor.chain().focus() as any).setFigure(v).run();
    },
    [editor]
  );

  const insertVideo = useCallback(
    (v: { src: string }) => {
      // setYouTubeVideo returns false for anything it cannot parse, so a bad
      // URL leaves the document untouched rather than inserting a dead block.
      editor.chain().focus().setYouTubeVideo({ src: v.src }).run();
    },
    [editor]
  );

  return (
    <div 
      className="fixed bottom-0 md:sticky md:top-0 md:bottom-auto left-0 right-0 z-40 bg-[var(--surface)]/95 backdrop-blur-md border-t md:border-t-0 md:border-b border-[var(--line)] py-2 md:mb-8 flex md:flex-wrap items-center gap-1 mx-auto w-full overflow-x-auto overflow-y-hidden md:max-w-3xl px-2 md:px-0 shadow-[0_-4px_12px_rgba(0,0,0,0.05)] md:shadow-none [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]"
      role="toolbar" 
      aria-label="Formatting"
    >
      {/* Group 1: History */}
      <ToolbarButton
        icon={Undo}
        onClick={() => editor.chain().focus().undo().run()}
        disabled={!editor.can().undo()}
        title="Undo (Ctrl+Z)"
      />
      <ToolbarButton
        icon={Redo}
        onClick={() => editor.chain().focus().redo().run()}
        disabled={!editor.can().redo()}
        title="Redo (Ctrl+Shift+Z)"
      />

      <Divider />

      {/* Group 2: Hierarchy & Style */}
      <ToolbarButton
        icon={Heading1}
        onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()}
        isActive={editor.isActive('heading', { level: 1 })}
        title="Heading 1"
      />
      <ToolbarButton
        icon={Heading2}
        onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
        isActive={editor.isActive('heading', { level: 2 })}
        title="Heading 2"
      />
      <ToolbarButton
        icon={Heading3}
        onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}
        isActive={editor.isActive('heading', { level: 3 })}
        title="Heading 3"
      />
      <ToolbarButton
        icon={Type}
        onClick={() => editor.chain().focus().setParagraph().run()}
        isActive={editor.isActive('paragraph')}
        title="Paragraph"
      />

      <Divider />

      <ToolbarButton
        icon={Bold}
        onClick={() => editor.chain().focus().toggleBold().run()}
        isActive={editor.isActive('bold')}
        title="Bold (Ctrl+B)"
      />
      <ToolbarButton
        icon={Italic}
        onClick={() => editor.chain().focus().toggleItalic().run()}
        isActive={editor.isActive('italic')}
        title="Italic (Ctrl+I)"
      />
      <ToolbarButton
        icon={Underline}
        onClick={() => editor.chain().focus().toggleUnderline().run()}
        isActive={editor.isActive('underline')}
        title="Underline (Ctrl+U)"
      />
      <ToolbarButton
        icon={Strikethrough}
        onClick={() => editor.chain().focus().toggleStrike().run()}
        isActive={editor.isActive('strike')}
        title="Strikethrough"
      />
      <ToolbarButton
        icon={SubscriptIcon}
        onClick={() => editor.chain().focus().toggleSubscript().run()}
        isActive={editor.isActive('subscript')}
        title="Subscript"
      />
      <ToolbarButton
        icon={SuperscriptIcon}
        onClick={() => editor.chain().focus().toggleSuperscript().run()}
        isActive={editor.isActive('superscript')}
        title="Superscript"
      />
      <ToolbarButton
        icon={Code}
        onClick={() => editor.chain().focus().toggleCode().run()}
        isActive={editor.isActive('code')}
        title="Inline Code"
      />

      <Divider />

      {/* Group 3: Lists & Quotes */}
      <ToolbarButton
        icon={List}
        onClick={() => editor.chain().focus().toggleBulletList().run()}
        isActive={editor.isActive('bulletList')}
        title="Bullet List"
      />
      <ToolbarButton
        icon={ListOrdered}
        onClick={() => editor.chain().focus().toggleOrderedList().run()}
        isActive={editor.isActive('orderedList')}
        title="Ordered List"
      />
      <ToolbarButton
        icon={Quote}
        onClick={() => editor.chain().focus().toggleBlockquote().run()}
        isActive={editor.isActive('blockquote')}
        title="Blockquote"
      />
      <ToolbarButton
        icon={Lightbulb}
        onClick={() => {
          editor.chain().focus().insertContent({
            type: 'callout',
            attrs: { type: 'takeaway' },
            content: [
              {
                type: 'heading',
                attrs: { level: 3 },
                content: [{ type: 'text', text: 'Key Takeaways' }]
              },
              {
                type: 'bulletList',
                content: [
                  {
                    type: 'listItem',
                    content: [{ type: 'paragraph' }]
                  }
                ]
              }
            ]
          }).run()
        }}
        title="Key Takeaways"
      />

      <span className="hidden sm:contents">
        <Divider />
        <ToolbarButton
          icon={AlignLeft}
          onClick={() => editor.chain().focus().setTextAlign('left').run()}
          isActive={editor.isActive({ textAlign: 'left' })}
          title="Align left"
        />
        <ToolbarButton
          icon={AlignCenter}
          onClick={() => editor.chain().focus().setTextAlign('center').run()}
          isActive={editor.isActive({ textAlign: 'center' })}
          title="Align centre"
        />
        <ToolbarButton
          icon={AlignRight}
          onClick={() => editor.chain().focus().setTextAlign('right').run()}
          isActive={editor.isActive({ textAlign: 'right' })}
          title="Align right"
        />
      </span>

      <Divider />

      {/* Group 4: Media & Embeds */}
      <ToolbarButton
        icon={ImagePlus}
        onClick={() => openMedia('image')}
        title="Insert image"
      />
      <ToolbarButton
        icon={MonitorPlay}
        onClick={() => openMedia('video')}
        title="Insert YouTube video"
      />
      <ToolbarButton
        icon={TableIcon}
        onClick={() => editor.chain().focus().insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run()}
        isActive={editor.isActive('table')}
        title="Insert table"
      />
      <ToolbarButton
        icon={Link2}
        onClick={setLink}
        isActive={editor.isActive('link')}
        title="Insert Link"
      />
      <ToolbarButton
        icon={FileCode}
        onClick={() => editor.chain().focus().toggleCodeBlock().run()}
        isActive={editor.isActive('codeBlock')}
        title="Code Block"
      />
      <ToolbarButton
        icon={Minus}
        onClick={() => editor.chain().focus().setHorizontalRule().run()}
        title="Horizontal Rule"
      />

      <Divider />

      {/* Group 5: View / Utilities */}
      <ToolbarButton
        icon={RemoveFormatting}
        onClick={() => editor.chain().focus().unsetAllMarks().clearNodes().run()}
        title="Clear Formatting"
      />
      {toggleFullscreen && (
        <ToolbarButton
          icon={Maximize2}
          onClick={toggleFullscreen}
          isActive={isFullscreen}
          title="Toggle Fullscreen"
        />
      )}

      <InsertMediaDialog
        key={mediaSession}
        kind={mediaKind ?? 'image'}
        open={mediaKind !== null}
        onClose={() => setMediaKind(null)}
        onInsertImage={insertImage}
        onInsertVideo={insertVideo}
      />
    </div>
  );
}

"use client";

import React, { useState, useTransition } from "react";
import { Role } from "@prisma/client";

import { claimReview, releaseReview, takeOverReview } from "@/app/actions/workflow";
import { showToast } from "@/lib/utils";
import { useRouter } from "next/navigation";
import ConfirmDialog from "../ui/ConfirmDialog";

interface Revision {
  id: string;
  notes: string | null;
  statusChange: string | null;
  createdAt: string | Date;
  user?: { name: string | null; email: string | null };
}

interface ReviewWorkspaceProps {
  userRole: string;
  userId: string;
  reviewerId: string | null;
  reviewerName?: string;
  articleId: string;
  currentStatus: string;
  revisions?: Revision[];
  onDecision: (status: string, notes: string) => Promise<void>;
}

export default function ReviewWorkspace({ userRole, userId, reviewerId, reviewerName, articleId, currentStatus, revisions = [], onDecision }: ReviewWorkspaceProps) {
  const [notes, setNotes] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showTakeOverConfirm, setShowTakeOverConfirm] = useState(false);
  const router = useRouter();

  // router.refresh() re-fetches the server component in the background and is
  // not awaitable. Wrapping it in a transition gives us isRefreshing, which
  // stays true until the new tree has actually committed -- so the buttons stay
  // disabled through the refresh instead of re-enabling over stale data the
  // moment the action resolves.
  const [isRefreshing, startRefresh] = useTransition();
  const busy = isSubmitting || isRefreshing;

  const refresh = () => startRefresh(() => router.refresh());

  const canReview = ["OWNER", "ADMIN", "EDITOR", "REVIEWER"].includes(userRole);

  const handleAction = async (status: string) => {
    if ((status === "REVISION_REQUESTED" || status === "REJECTED") && notes.trim().length < 20) {
      alert("Please provide at least 20 characters of notes explaining the decision.");
      return;
    }

    setIsSubmitting(true);
    try {
      await onDecision(status, notes);
      setNotes("");
      // Previously missing: the decision succeeded on the server but the page
      // kept rendering the old status until a manual reload.
      refresh();
    } catch (e) {
      console.error(e);
      alert("Failed to submit decision.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTakeOver = async () => {
    setShowTakeOverConfirm(false);
    setIsSubmitting(true);
    try {
      const res = await takeOverReview(articleId, true);
      if (res.ok) {
        showToast("Review taken over");
        refresh();
      } else {
        alert(res.message || "Action failed.");
      }
    } catch (e) {
      console.error(e);
      alert("An error occurred.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleWorkflowAction = async (actionFn: (id: string) => Promise<any>, successMsg: string) => {
    setIsSubmitting(true);
    try {
      const res = await actionFn(articleId);
      if (res.ok) {
        showToast(successMsg);
        refresh();
      } else {
        alert(res.message || "Action failed.");
      }
    } catch (e) {
      console.error(e);
      alert("An error occurred.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const isClaimedByMe = reviewerId === userId;
  const isClaimedByOther = reviewerId && reviewerId !== userId;
  const canTakeOver = ["OWNER", "ADMIN"].includes(userRole);

  const disableDecisions = Boolean(busy || (isClaimedByOther && !canTakeOver));

  return (
    <div className="cs-card" style={{ padding: "16px", marginBottom: "20px" }}>
      <h3 style={{ marginTop: 0, marginBottom: "16px", fontSize: "16px" }}>Review Workspace</h3>

      {/* Activity Timeline */}
      <div style={{ marginBottom: "20px", maxHeight: "250px", overflowY: "auto", paddingRight: "8px" }}>
        <h4 style={{ fontSize: "12px", textTransform: "uppercase", color: "var(--muted)", letterSpacing: "0.5px" }}>Activity Timeline</h4>
        {revisions.length > 0 ? (
          <div style={{ display: "flex", flexDirection: "column", gap: "12px", marginTop: "12px" }}>
            {revisions.map((rev) => (
              <div key={rev.id} style={{ fontSize: "13px", paddingLeft: "12px", borderLeft: "2px solid var(--line)" }}>
                <div style={{ display: "flex", justifyContent: "space-between", color: "var(--ink-muted)", marginBottom: "4px" }}>
                  <strong>{rev.user?.name || rev.user?.email || "Unknown User"}</strong>
                  <span style={{ fontSize: "11px" }}>{new Date(rev.createdAt).toLocaleString()}</span>
                </div>
                {rev.statusChange && (
                  <div style={{ 
                    display: "inline-block", 
                    padding: "2px 6px", 
                    borderRadius: "4px", 
                    background: "var(--surface-2)", 
                    fontSize: "11px",
                    fontWeight: 600,
                    marginBottom: "4px" 
                  }}>
                    &rarr; {rev.statusChange.replace("_", " ")}
                  </div>
                )}
                {rev.notes && (
                  <div style={{ background: "var(--surface-1)", padding: "8px", borderRadius: "6px", fontStyle: "italic" }}>
                    {rev.notes}
                  </div>
                )}
              </div>
            ))}
          </div>
        ) : (
          <p style={{ fontSize: "13px", color: "var(--ink-muted)", fontStyle: "italic", marginTop: "12px" }}>No revision history.</p>
        )}
      </div>

      {canReview && currentStatus === "SUBMITTED" && !reviewerId && (
        <div style={{ borderTop: "1px solid var(--line)", paddingTop: "16px", marginBottom: "16px" }}>
          <div style={{ padding: "12px", background: "var(--surface-1)", borderRadius: "6px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontSize: "13px" }}>This article is waiting for review.</span>
            <button className="btn-cs primary" onClick={() => handleWorkflowAction(claimReview, "Review claimed")} disabled={busy}>
              Claim Review
            </button>
          </div>
        </div>
      )}

      {canReview && isClaimedByMe && currentStatus !== "PUBLISHED" && (
        <div style={{ borderTop: "1px solid var(--line)", paddingTop: "16px", marginBottom: "16px" }}>
          <div style={{ padding: "12px", background: "rgba(16, 185, 129, 0.1)", color: "var(--success)", borderRadius: "6px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontSize: "13px", fontWeight: 600 }}>You have claimed this review.</span>
            <button className="btn-cs" onClick={() => handleWorkflowAction(releaseReview, "Review released")} disabled={busy}>
              Release Review
            </button>
          </div>
        </div>
      )}

      {canReview && isClaimedByOther && currentStatus !== "PUBLISHED" && (
        <div style={{ borderTop: "1px solid var(--line)", paddingTop: "16px", marginBottom: "16px" }}>
          <div style={{ padding: "12px", background: "var(--surface-1)", borderRadius: "6px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontSize: "13px", color: "var(--ink-muted)" }}>This review is claimed by another user.</span>
            {canTakeOver && (
              <button className="btn-cs danger" onClick={() => setShowTakeOverConfirm(true)} disabled={busy}>
                Take Over Review
              </button>
            )}
          </div>
        </div>
      )}

      <ConfirmDialog
        isOpen={showTakeOverConfirm}
        title="Take Over Review"
        description={`This review is currently claimed by ${reviewerName || 'another reviewer'}. Are you sure you want to take it over? They will lose their claim and any unsaved progress.`}
        confirmText="Take Over"
        onConfirm={handleTakeOver}
        onCancel={() => setShowTakeOverConfirm(false)}
      />

      {canReview && currentStatus !== "PUBLISHED" && (
        <div style={{ borderTop: "1px solid var(--line)", paddingTop: "16px" }}>
          <h4 style={{ fontSize: "12px", textTransform: "uppercase", color: "var(--muted)", letterSpacing: "0.5px", marginBottom: "8px" }}>Editorial Decision</h4>
          <textarea
            className="ed-input"
            rows={3}
            placeholder="Add review notes (min 20 chars for revision/rejection)..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            style={{ width: "100%", resize: "vertical", marginBottom: "4px" }}
          />
          <div style={{ fontSize: "11px", color: notes.length < 20 ? "var(--warning)" : "var(--success)", marginBottom: "12px", textAlign: "right" }}>
            {notes.length} / 20 min chars
          </div>
          <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
            <button 
              className="btn-cs" 
              onClick={() => handleAction("PUBLISHED")} 
              disabled={disableDecisions}
              style={{ background: disableDecisions ? "var(--surface-2)" : "var(--success)", color: disableDecisions ? "var(--muted)" : "white", borderColor: disableDecisions ? "var(--line)" : "var(--success)" }}
            >
              Approve & Publish
            </button>
            <button 
              className="btn-cs" 
              onClick={() => handleAction("REVISION_REQUESTED")} 
              disabled={disableDecisions}
            >
              Request Revision
            </button>
            <button 
              className="btn-cs" 
              onClick={() => handleAction("REJECTED")} 
              disabled={disableDecisions}
              style={{ color: disableDecisions ? "var(--muted)" : "var(--error)" }}
            >
              Reject
            </button>
          </div>
        </div>
      )}

      {!canReview && (currentStatus === "REVISION_REQUESTED" || currentStatus === "REJECTED") && (
        <div style={{ borderTop: "1px solid var(--line)", paddingTop: "16px" }}>
          <div style={{ padding: "12px", background: currentStatus === "REJECTED" ? "rgba(239, 68, 68, 0.1)" : "rgba(245, 158, 11, 0.1)", color: currentStatus === "REJECTED" ? "var(--error)" : "var(--warning)", borderRadius: "6px", fontSize: "13px" }}>
            <strong>{currentStatus === "REJECTED" ? "Article Rejected:" : "Action Required:"}</strong> {currentStatus === "REJECTED" ? "This article has been rejected and cannot be published." : "Please address the editorial notes above and resubmit your draft."}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React from "react";

interface SeoPreviewProps {
  title: string;
  description: string;
  slug: string;
  image?: string;
  siteName?: string;
}

export default function SeoPreview({
  title,
  description,
  slug,
  image,
  siteName = "xSypher",
}: SeoPreviewProps) {
  const truncatedTitle = title.length > 60 ? title.substring(0, 60) + "..." : title;
  const truncatedDesc = description.length > 155 ? description.substring(0, 155) + "..." : description;

  const url = `https://xsypher.com/article/${slug}`;

  return (
    <div style={{ marginTop: "16px", padding: "16px", border: "1px solid var(--line)", borderRadius: "var(--r-md)", background: "var(--bg-elevated)" }}>
      <h3 style={{ fontSize: "14px", fontWeight: 600, marginBottom: "12px", color: "var(--ink-main)" }}>Search Engine Preview</h3>

      <div style={{ padding: "12px", background: "#ffffff", borderRadius: "8px", border: "1px solid #dfe1e5", fontFamily: "arial, sans-serif" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "12px", marginBottom: "4px" }}>
          {image && (
