import React, { forwardRef, useEffect, useImperativeHandle, useState } from 'react'

interface SlashCommandItem {
  title: string
  description: string
  icon: string
  command: (props: { editor: any; range: any }) => void
}

export const SlashCommandList = forwardRef((props: any, ref) => {
  const [selectedIndex, setSelectedIndex] = useState(0)

  const selectItem = (index: number) => {
    const item = props.items[index]
    if (item) {
      props.command(item)
    }
  }

  const upHandler = () => {
    setSelectedIndex((selectedIndex + props.items.length - 1) % props.items.length)
  }

  const downHandler = () => {
    setSelectedIndex((selectedIndex + 1) % props.items.length)
  }

  const enterHandler = () => {
    selectItem(selectedIndex)
  }

  useEffect(() => setSelectedIndex(0), [props.items])

  useImperativeHandle(ref, () => ({
    onKeyDown: ({ event }: { event: KeyboardEvent }) => {
      if (event.key === 'ArrowUp') {
        upHandler()
        return true
      }
      if (event.key === 'ArrowDown') {
        downHandler()
        return true
      }
      if (event.key === 'Enter') {
        enterHandler()
        return true
      }
      return false
    },
  }))

  return (
    <div 
      className="slash-commands" 
      role="listbox"
      aria-label="Insert block"
      style={{ 
        background: "var(--surface)", 
        border: "1px solid var(--line)", 
        borderRadius: "var(--r-md)", 
        boxShadow: "0 4px 20px rgba(0,0,0,0.15)", 
        zIndex: 9999,
        maxHeight: '320px',
        overflowY: 'auto',
        width: '280px',
        padding: '4px',
      }}
    >
      {props.items.length > 0 ? (
        props.items.map((item: SlashCommandItem, index: number) => (
          <button
            role="option"
            aria-selected={index === selectedIndex}
            style={{ 
              display: "flex", 
              alignItems: "center",
              gap: "10px",
              width: "100%", 
              padding: "8px 10px", 
              textAlign: "left", 
              background: index === selectedIndex ? "var(--surface-2)" : "transparent",
              border: "none",
              borderRadius: "var(--r-sm)",
              color: "var(--ink)",
              cursor: "pointer",
              transition: "background .1s",
            }}
            key={index}
            onClick={() => selectItem(index)}
            onMouseEnter={() => setSelectedIndex(index)}
          >
            <span style={{ 
              width: '32px', 
              height: '32px', 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              background: 'var(--surface-3)',
              borderRadius: 'var(--r-sm)',
              fontSize: '16px',
              flexShrink: 0,
            }}>
              {item.icon}
            </span>
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: '13px', fontWeight: 600, fontFamily: 'var(--f-ui)' }}>
                {item.title}
              </div>
              <div style={{ fontSize: '11px', color: 'var(--muted)', lineHeight: '1.3', marginTop: '1px' }}>
                {item.description}
              </div>
            </div>
          </button>
        ))
      ) : (
        <div style={{ padding: "12px", color: "var(--muted)", fontSize: "13px", textAlign: "center" }}>
          No matching commands
        </div>
      )}
    </div>
  )
})

