  const todayDateFull = now.toLocaleDateString("en-US", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });
  const todayDateCompact = now.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    year: "numeric",
  });

  useEffect(() => {

    let ticking = false;

    const handleScroll = () => {
      if (!ticking) {
        window.requestAnimationFrame(() => {
          const y = window.scrollY;

          const navrow = document.getElementById("navrow");
          if (y > 140) {
            navrow?.classList.add("stuck");
          } else if (y < 120) {
            navrow?.classList.remove("stuck");
          }

          if (y > 100) {
            document.body.classList.add("scrolled");
          } else if (y < 20) {
            document.body.classList.remove("scrolled");
          }

          ticking = false;
        });
        ticking = true;
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", handleScroll);
      document.body.classList.remove("scrolled");
    };
  }, []);

  // Mobile Auto-Slide logic
  useEffect(() => {
    const navrowIn = document.getElementById("navrowIn");
