"use client";

import { useTheme } from "next-themes";
import { useEffect, useState } from "react";

export default function ThemeToggle() {
  const [mounted, setMounted] = useState(false);
  const { theme, setTheme, resolvedTheme } = useTheme();

  // Prevent hydration mismatch
  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <button className="icon-btn" aria-label="Toggle theme">
        <svg className="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round">
          <circle cx="12" cy="12" r="5" />
          <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
        </svg>
      </button>
    );
  }

  const isDark = resolvedTheme === "dark";

  return (
    <button 
      className="icon-btn" 
      onClick={() => setTheme(isDark ? "light" : "dark")}
      aria-label={`Switch to ${isDark ? "light" : "dark"} theme`}
    >
      {isDark ? (
        <svg className="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round">
          <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
        </svg>
      ) : (
        <svg className="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round">
          <circle cx="12" cy="12" r="5" />
          <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
        </svg>
      )}
    </button>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { subscribeNewsletter } from "@/app/actions/newsletter";

interface Props {
  className?: string;
  style?: React.CSSProperties;
  source?: string;
}

export default function NewsletterSignup({ className = "news-band", style, source = "HOMEPAGE" }: Props) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "success" | "already" | "error">("idle");
  const [errorMsg, setErrorMsg] = useState("");
  const [isPending, startTransition] = useTransition();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setStatus("error");
      setErrorMsg("Please enter a valid email address.");
      return;
    }

    startTransition(async () => {
      const res = await subscribeNewsletter(email, source);
      if (res.success) {
        setStatus("success");
      } else if ((res as any).code === "ALREADY_SUBSCRIBED") {
        setStatus("already");
      } else {
        setStatus("error");
        setErrorMsg(res.error || "Something went wrong. Please try again.");
      }
    });
  };

  return (
    <section className={className} style={style} aria-labelledby="nlH" data-reveal suppressHydrationWarning>
      <div>
        <h2 id="nlH">Get the biggest tech stories, <em>without the noise.</em></h2>
        <p>The xSypher Daily Brief — one email each morning with the stories that matter, our analysis, and nothing you didn't ask for. Free forever, unsubscribe anytime.</p>
      </div>
      <div>
        {status === "success" && (
          <div className="news-ok" role="status" aria-live="polite">
            <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <circle cx="12" cy="12" r="10" />
              <path d="m8 12.5 2.6 2.6L16 9.5" />
            </svg>
            <div>
              <b>You're on the list.</b>
              <span>Watch for the next Daily Brief in your inbox tomorrow morning.</span>
            </div>
          </div>
        )}

        {status === "already" && (
          <div className="news-ok" role="status" aria-live="polite">
            <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <circle cx="12" cy="12" r="10" />
              <path d="m8 12.5 2.6 2.6L16 9.5" />
            </svg>
            <div>
              <b>You're already subscribed.</b>
              <span>This email is already on the Daily Brief list.</span>
            </div>
          </div>
        )}

        {(status === "idle" || status === "error") && (
          <>
            <form className="news-form" id="nlForm" onSubmit={handleSubmit} noValidate aria-describedby="nlNote">
              <label className="sr-only" htmlFor="nlEmail">Email address</label>
              <input
                type="email"
                id="nlEmail"
                placeholder="you@example.com"
                required
                autoComplete="email"
                value={email}
                onChange={(e) => { setEmail(e.target.value); if (status === "error") setStatus("idle"); }}
                disabled={isPending}
                aria-invalid={status === "error"}
                aria-describedby={status === "error" ? "nlError" : "nlNote"}
              />
              <button className="btn btn-solid" type="submit" disabled={isPending}>
                {isPending ? "Subscribing…" : "Subscribe"}
              </button>
            </form>
            {status === "error" && (
              <p id="nlError" role="alert" aria-live="assertive" style={{ fontSize: "13px", color: "var(--error, #e53e3e)", marginTop: "6px" }}>
                {errorMsg}
              </p>
            )}
            <p className="news-note" id="nlNote">
              By subscribing you agree to our <Link href="/page/privacy" style={{ textDecoration: "underline" }}>privacy policy</Link>. We never sell your data or share your address. One email a day — that's the deal.
            </p>
          </>
        )}
      </div>
    </section>
  );
}

"use client";

import React, { useState, useRef, useEffect } from "react";
import { Loader2 } from "lucide-react";

export interface ComboboxOption {
  value: string;
  label: string;
}

interface CreatableComboboxProps {
  options: ComboboxOption[];
  value: string; // The current selected value (for single select)
  onChange: (val: string) => void;
  onCreate: (val: string) => Promise<string | null>; // Returns the new value (e.g., slug) on success
  placeholder?: string;
  isMulti?: boolean;
  selectedValues?: string[]; // For multi-select
  onSelectMultiple?: (vals: string[]) => void;
  id?: string;
}

export function CreatableCombobox({
  options,
  value,
  onChange,
  onCreate,
  placeholder = "Select or create...",
  isMulti = false,
  selectedValues = [],
  onSelectMultiple,
  id,
}: CreatableComboboxProps) {
  const [query, setQuery] = useState("");
  const [isOpen, setIsOpen] = useState(false);
  const [isCreating, setIsCreating] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const filteredOptions = options.filter(opt =>
    opt.label.toLowerCase().includes(query.toLowerCase())
  );

  const exactMatch = options.find(opt => opt.label.toLowerCase() === query.trim().toLowerCase());

  const handleSelect = (val: string, label: string) => {
    if (isMulti && onSelectMultiple) {
      if (!selectedValues.includes(label)) {
        onSelectMultiple([...selectedValues, label]);
      }
    } else {
      onChange(val);
      // Single select: don't keep query because we will derive input text from value
    }
    setIsOpen(false);
    setQuery("");
  };

  const handleCreate = async () => {
    const trimmed = query.trim();
    if (!trimmed) return;
    setIsCreating(true);
    try {
      const newVal = await onCreate(trimmed);
      if (newVal) {
        if (isMulti && onSelectMultiple) {
          if (!selectedValues.includes(trimmed)) {
            onSelectMultiple([...selectedValues, trimmed]);
          }
        } else {
          onChange(newVal);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsCreating(false);
      setIsOpen(false);
      setQuery("");
    }
  };

  // Determine what to show in the input box when NOT typing
  const displayValue = !isOpen && !isMulti ? (options.find(o => o.value === value)?.label || "") : query;

  return (
    <div className="relative w-full" ref={wrapperRef}>
      <div className="relative flex items-center w-full">
        <input
          id={id}
          ref={inputRef}
          type="text"
          className="ed-rail-input w-full pr-8"
          placeholder={isMulti && selectedValues.length > 0 ? "Add another..." : placeholder}
          value={displayValue}
          onChange={(e) => {
            setQuery(e.target.value);
            setIsOpen(true);
          }}
          onFocus={() => setIsOpen(true)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              if (exactMatch) {
                handleSelect(exactMatch.value, exactMatch.label);
              } else if (query.trim() && !isCreating) {
                handleCreate();
              }
            }
          }}
        />
        {isCreating && (
          <div className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--muted)]">
            <Loader2 className="w-4 h-4 animate-spin" />
          </div>
        )}
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full mt-1 bg-[var(--surface)] border border-[var(--line)] rounded-md shadow-lg max-h-60 overflow-auto">
          {filteredOptions.length > 0 ? (
            <ul className="py-1 m-0 list-none">
              {filteredOptions.map((opt) => (
                <li
                  key={opt.value}
                  onClick={() => handleSelect(opt.value, opt.label)}
                  className={`px-3 py-2 cursor-pointer text-sm transition-colors hover:bg-[var(--surface-2)] text-[var(--ink)] ${(isMulti ? selectedValues.includes(opt.label) : value === opt.value) ? "font-bold bg-[var(--surface-2)]" : ""
                    }`}
                >
                  {opt.label}
                </li>
              ))}
            </ul>
          ) : (
            <div className="px-3 py-2 text-sm text-[var(--muted)]">No matches found.</div>
          )}

          {query.trim() && !exactMatch && (
            <div
              className="px-3 py-2 border-t border-[var(--line)] cursor-pointer text-sm font-semibold text-[var(--accent)] hover:bg-[var(--surface-2)] transition-colors flex items-center gap-2"
              onClick={handleCreate}
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
              Create "{query.trim()}"
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { getServerSession } from "next-auth/next";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";

export async function getSession() {
  return await getServerSession(authOptions);
}

import { cache } from "react";
import { db } from "@/lib/db";
import { Role } from "@prisma/client";

export const getActor = cache(async () => {
  const session = await getSession();
  if (!session?.user?.id) return null;

  const user = await db.user.findUnique({
    where: { id: session.user.id },
    select: {
      id: true,
      role: true,
      isActive: true,
      authorId: true,
      name: true,
      email: true,
      sessionVersion: true,
    }
  });

  if (!user || !user.isActive || user.sessionVersion !== (session.user as any).sessionVersion) return null;
  return user as { id: string, role: Role, authorId: string | null, name: string | null, email: string | null };
});

export async function getCurrentUser() {
  return await getActor();
}

export async function requireRole(allowedRoles: string[]) {
  const user = await getCurrentUser();
  if (!user) {
    throw new Error("Unauthenticated. Please sign in.");
  }
  if (!allowedRoles.includes(user.role)) {
    throw new Error(`Unauthorized. Required role: ${allowedRoles.join(" or ")}. Your current role is: ${user.role}`);
  }
  return user;
}

// Add type declarations for NextAuth
import "next-auth";

declare module "next-auth" {
  interface User {
    id: string;
    role: string;
    sessionVersion?: number;
  }
  interface Session {
    user: User & {
      id: string;
      role: string;
      sessionVersion?: number;
    };
  }
}

import { Resend } from "resend";

// Constructed lazily. `new Resend(undefined)` throws "Missing API key" at
// construction time, so building it at module scope meant that merely importing
// this file crashed whenever RESEND_API_KEY was absent -- which is the normal
// state in local development, in CI, and for any newsroom running in-app
// notifications only.
//
// That was survivable while the only caller was the invitation flow, which is
// rare and deliberate. It stopped being survivable once lib/notifications.ts
// began importing this on every workflow transition: an unconfigured install
// would have thrown on import and taken the transition with it, exactly the
// failure the fail-soft notification contract exists to prevent.
let client: Resend | null = null;
function getResend(): Resend | null {
  if (!process.env.RESEND_API_KEY) return null;
  if (!client) client = new Resend(process.env.RESEND_API_KEY);
  return client;
}

interface SendInvitationEmailParams {
  to: string;
  role: string;
  inviteUrl: string;
}

export async function sendInvitationEmail({ to, role, inviteUrl }: SendInvitationEmailParams) {
  const resend = getResend();
  if (!resend) {
    // Unlike a workflow notification, an invitation that silently vanishes
    // strands a person who is waiting for a link, so this one reports rather
    // than skipping quietly. The caller surfaces the error.
    console.error("[email] RESEND_API_KEY is not set; invitation not sent to", to);
    return { success: false, error: "Email delivery is not configured." };
  }
  try {
    const { data, error } = await resend.emails.send({
      from: process.env.EMAIL_FROM_ADDRESS || "xSypher <noreply@xsypher.com>",
      to,
      subject: "You have been invited to join xSypher",
      html: `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #111; color: #fff; padding: 20px; border-radius: 8px;">
          <h1 style="color: #fff; border-bottom: 1px solid #333; padding-bottom: 10px;">x<span style="color: #666;">Sypher</span></h1>
          <p style="font-size: 16px; color: #ccc;">Hello,</p>
          <p style="font-size: 16px; color: #ccc;">You have been invited to join the xSypher newsroom as a <strong>${role}</strong>.</p>
          <p style="font-size: 16px; color: #ccc;">Click the link below to set up your account. This link will expire in 48 hours.</p>
          <div style="margin: 30px 0;">
            <a href="${inviteUrl}" style="background-color: #fff; color: #000; padding: 12px 24px; text-decoration: none; border-radius: 4px; font-weight: bold; display: inline-block;">Accept Invitation</a>
          </div>
          <p style="font-size: 14px; color: #666; border-top: 1px solid #333; padding-top: 20px;">
            If you did not expect this invitation, you can safely ignore this email.
          </p>
        </div>
      `,
    });

    if (error) {
      console.error("Resend error:", error);
      return { success: false, error: error.message };
    }

    return { success: true, data };
  } catch (error: any) {
    console.error("Failed to send invitation email:", error);
    return { success: false, error: error.message };
  }
}

export interface SendPasswordResetEmailParams {
  to: string;
